$string['settings:model_desc_dynamic'] = 'Leave blank to use the provider\'s default model automatically. Each provider has a built-in default that stays current (e.g. gpt-4o for OpenAI, claude-sonnet-4 for Claude, mistral-large-latest for Mistral). Only enter a model name if you want to override the default. If a model is misspelled or deprecated, [[tutorshort]] will automatically fall back to the provider\'s default.';
$string['settings:provider_gemini'] = 'Google Gemini';
$string['settings:quiz_hide_heading'] = 'Quiz Page Visibility';
$string['settings:quiz_hide_heading_desc'] = 'Control whether the [[tutorshort]] widget appears on Moodle quiz pages. This is stricter than the built-in summative quiz lock, which only disables chat during graded quizzes. These settings completely hide the widget on all quiz pages.';
$string['settings:rag_chunksize'] = 'Hamma Kutaa (jecha)';
$string['settings:rag_chunksize_desc'] = 'Lakkoofsi jechootaa kutaa qabiyyee tokkoon tokkoof yeroo meeshaa koorsii indeeksii gootu kaayyeffame. Kutaan xiqqaan caalaatti sirrii dha; kutaan guddaan haala dabalataa kenna.';
$string['settings:rag_return_scope'] = 'Bal\'ina Deebii Barbaacha';
$string['settings:rag_return_scope_desc'] = 'Argamiinsa tokkoo tokkoof maal akka galfamu kan murteessu. "chunk" (durtii) kutaa jechoota gara 400 ta\'e kan wal simate ni galcha. "window" kutaa wal simate ni galcha, kutaawwan fuula wal fakkaataa irraa isa ollaa ta\'an waliin. "page" fuula moduulii guutuu kan wal simiin sun keessatti argamu ni galcha. window/page yeroo deebiin fuula tokko keessatti bal\'atu gargaaru, kanaafis gaaffiin (prompt) guddaa uumama.';
$string['settings:rag_window_size'] = 'Bal\'ina Foddaa Barbaacha';
$string['settings:rag_window_size_desc'] = 'Bal\'ina "window" jedhuuf: lakkoofsa kutaalee ollaa kan gama lamaan kutaa wal simate irratti dabalamu. Durtiin 1.';
$string['settings:rag_parent_max_chars'] = 'Daangaa Lakkoofsa Qubee Kutaa Guddaa';
$string['settings:rag_parent_max_chars_desc'] = 'Lakkoofsi qubee guddaan kutaa "window"/"page" babal\'ifame. Fuulli daangaa darbe gara "window"tti, ergasii gara kutaa tokkootti deebi\'a. Durtiin 6000.';
$string['settings:rag_enabled'] = 'RAG dandeessisi (Barbaacha Hiikaa)';
$string['settings:rag_enabled_desc'] = 'Yeroo dandeessifame, barsiisaan AI qabiyyee koorsii gaaffii tokkoon tokkoof barbaachisu barbaacha hiikaatiin fida, qabiyyee hunda gaaffii sirnaa keessa guuruu mannaa.';
$string['settings:rag_heading'] = 'RAG / Barbaacha Hiikaa';
$string['settings:rag_heading_desc'] = 'Retrieval-Augmented Generation: qabiyyee koorsii akka embeddingitti indeeksii godhi, yeroo gaaffii immoo kutaalee baay\'ee barbaachisan qofa fidi. Itti fayyadama tokenii ni hir\'isa, gosa qabiyyee hundas ni deggera. API embedding barbaada.';
