$string['pedagogy:talking_avatar_desc'] = 'Yeroo banaa ta\'u, fuulli fakkii dubbatuu koorsii hunda keessatti ni dandeessifama yoo koorsiin sun jijjiirraa mataa isaa hin qabaanne. Dhiyeessaa qindaa\'e (D-ID, HeyGen, Tavus, ykn Synthesia Agents) armaan gadii barbaada; kanaan alatti wijeetichi beeksisa "dhiyeessaa qindeessi" jedhu agarsiisa, fakkichis hin sochoo\'u.';
$string['settings:talking_avatar_heading'] = 'Fakkii dubbatu';
$string['settings:talking_avatar_heading_desc'] = 'Yeroo iddoon fakkii dandeessifamu, gurgurtaan fakkii dubbatu kam akka [[tutorshort]] barattootaaf banu filadhu. [[tutorshort]] daraayvarota D-ID (istiriimingii WebRTC hunda caalaa gatii gadi aanaa), HeyGen (fakkii walqunnamsiisaa LiveKit irratti hundaa\'e), Tavus (Conversational Video Interface iframe keessa kaa\'amuu danda\'u), fi Synthesia Agents (oomisha ejentii yeroo dhugaa, daashboordii Synthesia keessatti qindaa\'u) waliin dhufa. Furtuun fi ID persona dhiyeessaa tokkoon tokkoo armaan gadii mul\'atu; dhiyeessaan filatame qofti guutamuu qaba. Waamichi gara alaa deemu hundi SSRF\'n ni mirkaneeffama.';
$string['settings:talking_avatar_provider'] = 'Dhiyeessaa fakkii dubbatu';
$string['settings:talking_avatar_provider_desc'] = 'Gurgurtaa furtuun fi ID persona isaa armaan gadiitti guutaman filadhu. Hanga dhaabbatichi mirkaneessutti akka <em>Homaa</em> tti dhiisi; durtiin barsiisummaa amma iyyuu <em>Durtii barsiisummaa</em> keessatti ni mul\'ata, garuu widgetichi fakkii mannaa beeksisa qindaa\'inaa agarsiisa.';
$string['settings:talking_avatar_provider_none'] = 'Homaa (fakkiin dhaamsame)';
$string['settings:talking_avatar_provider_did'] = 'D-ID Streaming Talks';
$string['settings:talking_avatar_provider_heygen'] = 'HeyGen Interactive Avatar';
$string['settings:talking_avatar_provider_tavus'] = 'Tavus Conversational Video';
$string['settings:talking_avatar_provider_synthesia'] = 'Synthesia Agents (yeroo dhugaa)';
$string['settings:talking_avatar_did_api_key'] = 'Furtuu API D-ID';
$string['settings:talking_avatar_did_api_key_desc'] = 'Sarara <code>email:api-key</code> Base64\'n koodeffame kan <a href="https://studio.d-id.com/account-settings" target="_blank" rel="noopener">D-ID Studio → Account → API keys</a> irraa argamu. Akka <code>Authorization: Basic …</code> tti ergama.';
$string['settings:talking_avatar_did_persona_id'] = 'URL suuraa madda D-ID';
$string['settings:talking_avatar_did_persona_id_desc'] = 'URL HTTPS ummataaf banaa kan suuraa dhaabbataa D-ID sochoosu (yookiin URL dhiheessaa Studio kan akka <code>https://create-images-results.d-id.com/…</code>). Istiriimii tokkoon tokkoof ni barbaachisa.';
$string['settings:talking_avatar_heygen_api_key'] = 'Furtuu API HeyGen';
$string['settings:talking_avatar_heygen_api_key_desc'] = 'Furtuu API kan <a href="https://app.heygen.com/settings?nav=API" target="_blank" rel="noopener">HeyGen → Settings → API</a> irraa argamu. Akka <code>X-Api-Key</code> tti ergama.';
$string['settings:talking_avatar_heygen_persona_id'] = 'ID fakkii walqunnamsiisaa HeyGen';
$string['settings:talking_avatar_heygen_persona_id_desc'] = 'ID fakkii daashboordii HeyGen Streaming Avatar irraa (fkn. <code>Tyler-incasualsuit-20220721</code>).';
$string['settings:talking_avatar_tavus_api_key'] = 'Furtuu API Tavus';
$string['settings:talking_avatar_tavus_api_key_desc'] = 'Furtuu API kan <a href="https://platform.tavus.io/api-keys" target="_blank" rel="noopener">Tavus platform → API keys</a> irraa argamu. Akka <code>x-api-key</code> tti ergama.';
$string['settings:talking_avatar_tavus_persona_id'] = 'ID replica Tavus';
$string['settings:talking_avatar_tavus_persona_id_desc'] = 'ID replica (fakkeenya leenjifame) kan [[tutorshort]] akka isaatti haasa\'u barbaaddu. Yoo barbaachise ID persona dirree furtuu API irratti dabaluun walitti makuu dandeessa; [[tutorshort]] <code>persona_id</code> ni dabarsa.';
$string['settings:talking_avatar_synthesia_api_key'] = 'Furtuu API Synthesia';
$string['settings:talking_avatar_synthesia_api_key_desc'] = 'Furtuu API kan <a href="https://app.synthesia.io/#/account/api" target="_blank" rel="noopener">Synthesia → Account → API</a> irraa argamu. Akka mataduree <code>Authorization</code> tti ergama (Synthesia furtuu qulqulluu ni fudhata).';
$string['settings:talking_avatar_synthesia_persona_id'] = 'ID ejentii Synthesia';
$string['settings:talking_avatar_synthesia_persona_id_desc'] = 'ID ejentii daashboordii Synthesia Agents keessatti uumame. Beekumsi, personaan fi maddi hayyamame gama ejentiitiin qindaa\'u; [[tutorshort]] ID kana irratti seeshinii banuu qofa.';
$string['talking_avatar:disabled'] = 'Fakkiin dubbatu koorsii kanaaf hin dandeeffamne.';
$string['talking_avatar:unconfigured'] = 'Fakkiin dubbatu dandeeffameera garuu dhiyeessaan qindaa\'e tokkollee hin jiru. Bulchaan qindaa\'ina pilaagiinii keessatti dhiyeessaa filatee ragaa eenyummaa galchuu qaba.';
$string['talking_avatar:session_failed'] = 'Dhiyeessaan fakkii dubbatuu gaaffii marii dide. Qindaa\'ina dhiyeessaa ilaali yookiin yeroo muraasa booda irra deebi\'ii yaali.';
$string['talking_avatar:viewer_title'] = 'Fakkii dubbatu [[tutorshort]]';
$string['talking_avatar:bundle_required'] = 'Ilaaltuun fakkii dubbatuu bandilii CDN [[tutorshort]] kan qindaa\'e barbaada. Bulchaan qindaa\'ina pilaagiinii keessatti URL bandilii CDN akka qindeessu gaafadhu.';
$string['talking_avatar:open'] = 'Fakkii bani';
$string['talking_avatar:close'] = 'Fakkii cufi';
$string['settings:avatar_rate_card_overrides'] = 'Bakka buusa kaardii gatii fakkii (JSON)';
$string['settings:avatar_rate_card_overrides_desc'] = 'Wanti JSON dhiyeessaa fakkii tokkoon tokkoon furtuu godhate kan gatii USD daqiiqaa tokkoon qabu. Dhiyeessaa sanaaf gatii ergame bakka bu\'a. Fakkeenya: <pre>{ "did": 0.18, "heygen": 0.40, "tavus": 0.25 }</pre> Duwwaa = durtii v4.10.0 waliin ergame fayyadami: D-ID $0.30/daqiiqaa, HeyGen $0.50/daqiiqaa, Tavus $0.30/daqiiqaa, Synthesia $0.40/daqiiqaa. Akka daashboordiin xiinxalaa baasii dhugaa dhaabbatichaa calaqqisiisuuf kana gara gatii waliigaltee keetiitti qindeessi.';
$string['settings:talking_avatar_did_webhook_secret'] = 'Iccitii mallattoo webhook D-ID';
$string['settings:talking_avatar_did_webhook_secret_desc'] = 'Filannoo dha. Yeroo qindaa\'u, D-ID taatee dhuma seeshinii gara <code>{wwwroot}/local/ai_course_assistant/talking_avatar_webhook.php?provider=did</code> POST gochuu danda\'a, iccitii kanaan akka <code>X-DID-Signature</code> (hex HMAC-SHA256) mallattaa\'ee. Sararri webhook heartbeat fuula duraa irra dursa qaba. Duwwaa = qabduun cufaa dha, heartbeat fi haxaa\'aan sa\'aatii sa\'aatiin deemu dhuma seeshinii kophaa isaanii to\'atu.';
$string['settings:talking_avatar_heygen_webhook_secret'] = 'Iccitii mallattoo webhook HeyGen';
$string['settings:talking_avatar_heygen_webhook_secret_desc'] = 'Filannoo dha. Yeroo qindaa\'u, HeyGen taatee dhuma seeshinii iccitii kanaan akka <code>X-HeyGen-Signature</code> (hex HMAC-SHA256) mallattaa\'e POST gochuu danda\'a. Duwwaa = qabduun cufaa dha.';
$string['settings:talking_avatar_tavus_webhook_secret'] = 'Iccitii mallattoo webhook Tavus';
$string['settings:talking_avatar_tavus_webhook_secret_desc'] = 'Filannoo dha. Yeroo qindaa\'u, Tavus taatee dhuma haasawaa iccitii kanaan akka <code>X-Tavus-Signature</code> (hex HMAC-SHA256) mallattaa\'e POST gochuu danda\'a. Duwwaa = qabduun cufaa dha.';
$string['settings:talking_avatar_synthesia_webhook_secret'] = 'Iccitii mallattoo webhook Synthesia';
$string['settings:talking_avatar_synthesia_webhook_secret_desc'] = 'Filannoo dha. Yeroo qindaa\'u, Synthesia taatee dhuma seeshinii ejentii iccitii kanaan akka <code>X-Synthesia-Signature</code> (hex HMAC-SHA256) mallattaa\'e POST gochuu danda\'a. Duwwaa = qabduun cufaa dha.';
