$string['settings:prompt_debug_enabled']      = 'Log assembled system prompt to file';
$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = 'Gaaffii haalata Sokraatik bal\'aa';
$string['settings:socratic_verbose_desc'] = 'Yeroo banaa ta\'u, koorsiiwwan haalata Sokraatik qajeelfama godhi/hin godhin guutuu tokenii gara 600 kan jalqaba v3.9.30 keessatti dabalame ni fudhatu. Yeroo cufaa ta\'u (durtii), qajeelfama sarara tokkoo kan moodeelonni ammayyaa keessummeeffaman amanamummaadhaan hordofan ni fudhatu, kunis marii tokkoon tokkoon tokenii gara 600 qusata. Yoo koorsiin tokko moodeelii ofiin keessummeeffame dadhabaa kan deggersa ifa ta\'e barbaadu irratti hojjechaa jiraate kana bani.';
$string['settings:prompt_budget_chars'] = 'Baajata qubee gaaffii sirnaa';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'Daangaa qabiyyee fuula ammaa (qubee)';
$string['settings:current_page_content_maxchars_desc'] = 'Yeroo RAG cufaa ta\'e, baay\'inni guddaan qubeewwan barreeffama fuula ammaa kan akka kutaa "Current Page Content" gaaffii sirnaa keessa galchame. Durtii 8,000 gaaffiwwan fuula-addaa gaariitti hundeessa utuma caasaafi qajeelfamaaf baajata hambisuu. (RAG yoo banaa ta\'e, fuulli qooda isaa kutaawwan wal-qabatan ofii isaatiin hundaa\'a, gara fuula ammaatti dabaa, kanaaf daangaan kun hin hojjetu.) Fuulli baay\'ee dheeraan jalqabarraa hamma baay\'ina qubee kanaa kutama, kanaafuu eegeen fuula akkaan dheeraa hin caqasamu ta\'a; RAG banuun kana ni oolcha. Saayitoonni baasii hubatan gadi daangessuu danda\'u (fkn. 3,000-4,000). Hangi 500-8,000 daangeffame. <code>prompt_budget_chars</code> irraa walaba: kun kutaa fuula qofa daangessa; baajatni gaaffii guutuu daangessa.';
$string['settings:prompt_verbosity'] = 'Bal\'ina gaaffii';
$string['settings:prompt_verbosity_desc'] = 'Bal\'ina durtii kutaalee qajeelfamaa (haalata Sokraatik, qabeenya alaa). Gabaabaan (durtii) waan moodeelonni ammayyaa keessummeeffaman amanamummaadhaan hordofanii dha; idileen moodeelota giddu-galeessaaf deggersa ifa ta\'e dabala; bal\'aan qajeelfama ulfaataa bara v3.9.30 moodeelota ofiin keessummeeffaman dadhaboof qabata. Bakka buusuun koorsii tokkoon tokkoon karaa <code>prompt_verbosity_course_&lt;id&gt;</code> ni argama.';
$string['settings:prompt_verbosity_concise'] = 'Gabaabaa (moodeelota keessummeeffamaniif ni gorfama)';
$string['settings:prompt_verbosity_standard'] = 'Idilee';
$string['settings:prompt_verbosity_verbose'] = 'Bal\'aa (moodeelota ofiin keessummeeffaman dadhaboof)';
$string['settings:prompt_metrics_enabled'] = 'Safartuu gaaffii kutaa tokkoon tokkoon qabi';
$string['settings:prompt_metrics_enabled_desc'] = 'Yeroo banaa ta\'u (durtii), marii tokkoon tokkoon isaa gaaffii walitti qabame tokkoon tokkoof sarara JSON tokko gara <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code> lakkoofsa qubee gosa tokkoon tokkoo waliin barreessa. Guyyoonni 7 dhumaa ni qabamu. Fuulli bulchiinsa safartuu kana walitti qabee gorsa baajataaf dhiyeessa. Odeeffannoon nama adda baasu hin galmeeffamu — hammi kutaa qofa. Yoo dhaabbanni kee faayilii safartuu gonkumaa hin barbaanne cufi.';
$string['settings:prompt_budget_auto_tune'] = 'Sirreeffama ofumaa guyyuu baajata gaaffii sirnaa (kan hafe)';
$string['settings:prompt_budget_auto_tune_desc'] = 'Kan hafe. Yoo haalli baajataa gubbaa <strong>Kan hin jijjiiramne</strong> irratti hin qindaa\'in wanta tokko hin hojjetu. Hojiin guyyuu tokko kutamuu ilaaluu fi gaaffii guddicha argee duukaa bu\'uudhaan baajata qubee tilmaama ture. Baajata foddaa hiikaa moodeelaa irraa argachuun kana caalaatti hojjeta: hin raafamu, ragaa jalqabaas hin barbaadu. Lamaanuu walitti bu\'iinsa qabu turan, sababiin isaas hojiin sun baajata qubee waan barreessuuf, gatiin durtii hin taane kamiyyuu baajata argame ni dhaamsa. Kana dhaamsuun dhiisi; gadhiisa fuulduraa keessatti ni haqama. Gorsi ammallee fuula <a href="/local/ai_course_assistant/prompt_metrics.php">Safartuu gaaffii</a> irratti ni mul\'ata.';
$string['task:auto_tune_prompt_budget'] = 'Baajata gaaffii [[tutorshort]] safartuu argame irraa ofumaan sirreessuu';
$string['prompt_metrics:title'] = 'Safartuu gaaffii + gorsa baajataa';
$string['prompt_metrics:subtitle'] = 'Guddina gaaffii kutaa tokkoon tokkoon guyyoota 7 darban keessa qabame. Qindaa\'ina baajata qubee gaaffii sirnaatiif gatii gorsuuf itti fayyadama.';
$string['prompt_metrics:no_data'] = 'Safartuun gaaffii ammatti hin galmoofne. Herrega barataa irraa marsaa chaattii muraasa ergi, ergasii fuula kana haaromsi. (Yoo mallattoon safartuu qabuu qindaa\'ina pilaagiinii keessatti cufaa ta\'e, daataan hin walitti qabamu.)';
