$string['task:milestone_check'] = 'Imeelii yaadannoo milkaa\'inaa guyyuu erguu (v5.3.0)';
$string['task:struggle_signal_review'] = 'Mallattoolee rakkinaa gamaaggamanii gara yaadannoo dhuunfaa barataatti galchuu (v5.3.0)';
$string['empathy:title'] = 'Qunnamtii gara-laafinaa fi yaadannoo darbee-dhufe (v5.3.0)';
$string['empathy:desc'] = 'Amaloota walsimsiifaman sadi kan [[tutorshort]] akka leenjisaa dhaggeeffatu tokkootti akka dhaga\'amu godhan. Galmoonni sababa barataan as jiruuf ni qabatu. Yaadannoon darbee-dhufe waan duraan rakkisaa ture ni yaadata, kanaaf [[tutorshort]] kallattii biraa dhiheessuu danda\'a. Sadarkaaleen milkaa\'inaa guyyoota walitti aansuu fi xumura koorsii imeeliidhaan ni kabaju. Amalli tokkoon tokkoon qabduu dhaamsuu of-danda\'e fi filannoo barataa qaba. Mallattoon rakkinaa gonkumaa chaattii keessaa hin ba\'u — waa\'ee marii rakkisaa imeeliin tokkollee hin ergamu.';
$string['empathy:outreach_master_enabled'] = 'Qabduu guddaa qunnamtii dhaamsu';
$string['empathy:outreach_master_enabled_desc'] = 'Dhaabbata haaraa irratti durtiidhaan cufaadha. Yeroo cufaa ta\'u, qabduuwwan amala tokkoon tokkoo armaan gadii kamiyyuu osoo hin ilaalin, imeeliin gara-laafinaa gosa kamiyyuu GONKUMAA hin ergamu. Durtii amala tokkoon tokkoo fi adeemsa hayyama barataa erga ilaaltee booda kana bani.';
$string['empathy:goals_enabled'] = 'Marii galma ogummaa dandeessisi';
$string['empathy:goals_enabled_desc'] = 'Barattoonni deebii gabaabaa lama (maaliif as akka jiran, maal ta\'uu akka barbaadan) fedhiidhaan akka kennan hayyama; kunis dhuunfeessuu keessa gala. Chaattii keessa qofa; imeeliin hin jiru. Banaa dhiisuun nagaa dha.';
$string['empathy:milestones_enabled'] = 'Imeelii yaad-deebii sadarkaa milkaa\'inaa dandeessisi';
$string['empathy:milestones_enabled_desc'] = 'Yeroo barataan guyyaa 7 walitti aansuu, guyyaa 30 walitti aansuu, yookiin xumura koorsii ga\'u imeelii gabaabaa ho\'aa erga. Qabduu guddaa armaan olii fi hayyama barataa tokkoon tokkoo isaa barbaada. Karaalee hunda irratti barataa tokkoof guyyaa 7 keessatti imeelii tokko qofa — daangaa cimaa.';
$string['empathy:memory_enabled'] = 'Yaadannoo dhuunfeessuu darbee-dhufe dandeessisi';
$string['empathy:memory_enabled_desc'] = '[[tutorshort]] waa\'ee waan barataa tokkotti rakkisaa ture yaadannoo dhuunfaa xixiqqaa marii gidduutti akka baatu hayyama, kanaaf deebiin itti aanu kallattii biraa dhiheessuu danda\'a. Daangeffameera (barataa tokkoof koorsii tokkotti yaadannoo 5 ol miti, umurii guyyaa 90). Barataan gulaaluu danda\'a. Barsiisotaaf gonkumaa hin mul\'atu.';
$string['empathy:struggle_enabled'] = 'Ramaddii rakkinaa dandeessisi';
$string['empathy:struggle_enabled_desc'] = 'Durtiidhaan cufaadha. [[tutorshort]] marsaawwan hedduu keessatti dhiphina itti fufe akka adda baasu fi yaadannoo darbee-dhufe armaan olii keessatti yaadannoo iddoo rakkoo calluma jedhee akka galmeessu hayyama. Bu\'aan chaattii keessa qofa; waa\'ee marii rakkinaa imeeliin gonkumaa hin ergamu. Daataan mallattoo guyyaa 7 booda ofumaan haqama.';
$string['empathy:outreach_dryrun'] = 'Qunnamtii yaalii (osoo hin ergin galmeessuu)';
$string['empathy:outreach_dryrun_desc'] = 'Yeroo banaa ta\'u, hojiin karoorfame sadarkaa milkaa\'inaa akka waan imeelii ergeetti sararoota audit ni galmeessa garuu dhugumatti nama tokkollee imeelii hin ergu. Sirni yeroo boqonnaa fi hayyamaa dhugumaan hojjechuu isaa osoo hojiitti hin galin dura mirkaneessuuf dhaabbata haaraa irratti kana fayyadami.';
$string['goals:save'] = 'Galmoota koo olkaa\'i';
$string['goals:dismiss'] = 'Amma miti';
$string['goals:edit'] = 'Galmoota gulaali';
$string['goals:clear'] = 'Galmoota koo haqi';
$string['comms:title'] = 'Qunnamtiiwwan koo';
$string['comms:desc'] = 'Imeelii ofumaan ergaman kam [[tutorshort]] siif erguu akka danda\'u filadhu. Durtiin cufaadha. Yeroo barbaaddetti jijjiiruu dandeessa.';
$string['comms:milestones_label'] = 'Yeroo sadarkaa milkaa\'inaa ga\'u imeelii naaf ergi (guyyaa 7 walitti aansee, guyyaa 30 walitti aansee, xumura koorsii).';
