// v5.10.x strings (token-aware budgeting, backend retry, self-test, deployment presets, escalation consent, privacy).
$string['settings:backend_context_tokens'] = 'Foddaa kallattii baackandii (tookonota)';
$string['settings:backend_context_tokens_desc'] = 'Dheerina kallattii ol\'aanaa (max_model_len) baackandii AI keetii, tookonotaan. Moodeloota qabaman foddaa guddaa qabaniif 0 irra kaa\'i (hir\'isuun hin jiru). Yeroo 0 oliitti kaa\'amu (fakkeenyaaf 8192 baackandii vLLM ofiin-qaban irratti), [[tutorshort]] baajata qubee gaaffii-sirnaa armaan olii ni xiqqeessa akka gaaffiin dabalataan bu\'aa qabame fi seenaa marii foddaa keessatti galu, afaanota tookonni itti baay\'ataa ta\'an keessattillee. Akkaataan kun fayyadamtoota walfaana jiraniin akkamitti mappii ta\'u beekuuf fuula wiikii Deployment Sizing ilaali.';
$string['settings:backend_retry_attempts'] = 'Yaaliiwwan irra deebii baackandii';
$string['settings:backend_retry_attempts_desc'] = 'Dogoggora baackandii yeroof (HTTP 429 ykn 503) barataaf dogoggora agarsiisuun dura yeroo meeqa irra deebi\'amee yaalamu. Yaaliiwwan irra deebii kan ta\'an barreeffamni deebii kamiyyuu utuu hin istiriimamiin dura qofa, kanaaf bu\'aan gonkumaa hin lamaatu. Baackandiiwwan xixiqqoo ofiin-qabaman kanneen baay\'ina jala gaaffiiwwan didaniif kan akeekkame. Dhaamsuuf 0 irra kaa\'i. Durtii 2.';
$string['settings:backend_retry_max_wait'] = 'Eegumsa ol\'aanaa irra deebii baackandii (sekoondii)';
$string['settings:backend_retry_max_wait_desc'] = 'Daangaa ol\'aanaa, sekoondiidhaan, irra deebi\'uun dura mata-duree Retry-After baackandii irraa hammam dheeraa kabajamu. Yeroo baackandiin Retry-After hin ergine, [[tutorshort]] qooda isaa baakooffii eksipooneenshiyaalii gabaabaa fayyadama. Durtii 5.';
$string['prompt:truncation_hint'] = 'HUBACHIISA: Sababa daangaa dheerinaatiin marsaa kana qabiyyee koorsii guutuu barbaaduun hin danda\'amne. Yoo barataan waa\'ee waan qabiyyee kennametti argachuu hin dandeenye gaafate, koorsii guutuu barbaaduu akka hin dandeenye himi, akkasumas koorsii keessa hin jiru jechuu mannaa fuula ykn sochii mata-dureen sun itti haammatame addaa banachuu akka qaban gorsi.';
$string['selftest:title'] = 'Of-qoraannoo baackandii';
$string['selftest:intro'] = 'Hordoffii kallattii baackandii AI sirreeffame keetii dalagsiisi: marii xiqqaa deebi\'ee deemu, adda baasuu ofumaan foddaa kallattii (max_model_len) fi qindaa\'ina foddaa kallattii baackandii keetii waliin wal-bira qabuu, daangaa gadii baajata gaaffii-sirnaa, fi (yeroo RAG banaa ta\'u) embeeddiingii deebi\'ee deemu. Bilbilli neetwoorkii kan dalagu yeroo Dalagsiisi cuqaaftu qofa.';
