$string['coursesettings:apibaseurl_rejected'] = 'URL bu\'uura API hin qabamne: dhuma HTTPS uummataa kan qorannoo nageenyaa SSRF darbu ta\'uu qaba.';
$string['settings:escalation_intent_patterns'] = 'Bifata kaayyoo ol guddisuu';
$string['settings:escalation_intent_patterns_desc'] = 'PCRE, no delimiters. Sarara tokkoon tokkoon isaanii irratti ibsa idilee tokko; sararoonni # tiin jalqaban ni dhiifamu. Tikeetiin deeggarsaa kan banamu yeroo ergaan barataan mataan isaa isaan keessaa tokkoon wal simu qofa, kanaafuu qabiyyeen koorsii bakka barataa buʼee ol guddisuu kakaasuu hin dandaʼu. Duraa duubaan ijaaraman fayyadamuuf duwwaa dhiisi; isaan Ingiliffaa fi jechoota beekamoo Ispaanish, Faransaay, Jarmanii fi Portugaal keessatti argaman ni haammatu. Marsariitiiwwan barattoonni isaanii afaan biraatiin barreessan asitti bifata haa dabalan: ergaan wal hin simne tikeetiin akka hin banamne agarsiisa.';
$string['settings:zendesk_require_consent'] = 'Deeggarsaaf ol-guddisuun dura eeyyama barbaachisaa';
$string['settings:zendesk_require_consent_desc'] = 'Yeroo banaa ta\'u (gorfame), [[tutorshort]] marii gara deeskii deeggarsa Zendesk kan ol-guddisu erga barataan beeksisa eeyyama yeroo jalqabaa fudhatee booda qofa, kunis gargaarsa namaa gaafachuun marii (maqaa fi imeelii dabalatee) deeggarsa waliin akka qooddatu ifa godha. Kana kan cufitu yoo eeyyama sana karaa biraan argatte qofa; cufaa ta\'ee, ol-guddisuun battalumatti ergama. Ol-guddisuun Zendesk hojiirra kan oolu yoo ta\'e malee dhiibbaa hin qabu.';
$string['chat:escalation_needs_consent'] = 'Kun miseensa garee deeggarsa keenyaa barbaachisuu kan fakkaatu. Isaanitti dabarsuuf marii kana, maqaa fi imeelii kee dabalatee, deeskii deeggarsa waliin qooduun qaba. Ati ammatti kanaaf walii hin galle, kanaaf homaa hin ergine. Yoo gargaarsa namaa barbaadde, mee beeksisa daataa-qoodinsa gargaaraa kanaaf fudhadhuutii ammas gaafadhu, ykn kallattiidhaan deeggarsa qunnami.';
$string['privacy:metadata:email_optout'] = 'Filannoowwan ala-bahuu imeelii tokkoo tokkoo fudhataa (gosa imeelii kam irraa fudhataan biyya gale).';
$string['privacy:metadata:email_optout:email'] = 'Teessoo imeelii fudhataa kan ala-bahuun irratti raawwatamu.';
$string['privacy:metadata:email_optout:optout_type'] = 'Gosa imeelii fudhataan ala bahe.';
$string['privacy:metadata:email_optout:userid'] = 'Yoo beekame, fayyadamaa Moodle kan ala-bahuun kan isaa ta\'e.';
$string['chat:consent_scroll_hint'] = 'Itti fufuun dura beeksisa guutuu dubbisuuf maaloo gara gadiitti gad deemi.';
$string['settings:rag_min_similarity'] = 'Wal-qabsiisummaa Xiqqaa (koosaayinii)';
$string['settings:rag_min_similarity_desc'] = 'Kutaawwan argaman kanneen wal-fakkeenyi koosaayinii isaanii gaaffii waliin gatii kana gadi ta\'e haqi, akka gaaffiin mata duree alaa yookiin odeeffannoo gabaabaa qabu yeroo hunda wal-simannaa laafaadhaan hanga Top-K guutuu mannaa caqasoota xiqqaa (yookiin duwwaa) galchu. Hangi 0 hamma 1; 0 balbala kana ni dhaamsa. Gatiin sirrii moodeela embedding irratti hundaa\'a: 0.25 text-embedding-3-small\'f ni mijata. Cimaa taasisuuf ol kaasi (haala xiqqaa, mata duree waliin wal-qabataa caalu), bal\'inaan fudhachuuf gadi buusi.';
$string['settings:rag_currentpage_boost'] = 'Dabalata Fuula Ammaa';
$string['settings:rag_currentpage_boost_desc'] = 'Badhaasni xiqqaan qabxii wal-qabsiisummaa kutaawwan fuula barataan amma ilaalaa jiruu irratti dabalamu, akka gaaffiwwan akka "kana ibsi" yeroo qabxiin walitti dhiyaatu fuula mul\'atu filatan. Tartiiba qofa: kutaa fuula wal-hin qabne balbala wal-qabsiisummaa xiqqaa darbuuf hin dirqisiisu. Dhaamsuuf 0 godhi.';
$string['settings:history_mode'] = 'Haala Filannoo Seenaa';
$string['settings:history_mode_desc'] = 'Dabareewwan haasawaa darbanii akkamitti dura moodeelaaf ergaman filatamu. <strong>Hiika-qabeessa</strong> dabareewwan dhiheenyaa gaaffii ammaa waliin wal-qabatan qofa qabata (yeroo hunda jijjiirraa dhiheenyaa), akka dabareen dur darbe kan dulloomeefi mata duree alaa baasii hin guddifne yookiin deebii karaa irraa hin maqsine; ergaa tokkoof waamicha embedding dabalataa tokko godha. <strong>Dhiheenya</strong> wal-qabsiisummaa osoo hin ilaalin cimdiiwwan dhumaa "Max Conversation History" qabata (amala yeroo dheeraa, waamicha dabalataa hin qabu). Yoo embedding hin argamne, haalli hiika-qabeessa ofumaan gara dhiheenyaatti deebi\'a.';
$string['settings:history_mode_semantic'] = 'Hiika-qabeessa (dabareewwan dhiheenyaa wal-qabatan)';
$string['settings:history_mode_recency'] = 'Dhiheenya (cimdiiwwan N dhumaa)';
$string['settings:history_semantic_minscore'] = 'Daangaa Gadii Wal-qabsiisummaa Seenaa (koosaayinii)';
$string['settings:history_semantic_minscore_desc'] = 'Haala seenaa hiika-qabeessa keessatti, dabareen darbe yoo wal-fakkeenyi isaa gaaffii ammaa waliin yoo xiqqaate gatii kana ta\'e qofa qabama (jijjiirraan dhiheenyaa yeroo hunda qabama). Hangi 0 hamma 1; moodeela irratti hundaa\'a. Cimaa taasisuuf ol kaasi (seenaa xiqqaa), caalaa qabachuuf gadi buusi.';
$string['settings:history_candidates'] = 'Foddaa Filannoo Seenaa';
$string['settings:history_candidates_desc'] = 'Haala seenaa hiika-qabeessa keessatti, cimdiiwwan dhiheenyaa baay\'ina kanaa qofatu wal-qabsiisummaadhaan qabxii argata (daangaa baasii). Cimdiiwwan foddaa kanaa ol dulloomanii hin ergaman. Kana "Max Conversation History" irratti yookiin isaa ol qabi.';

// v5.11.0 - v6.2.0 strings (added 2026-06-10).
$string['settings:embed_provider_voyage'] = 'Voyage AI (voyage-3.5 — gorfame; +4 MTEB vs OpenAI 3-small, 4x context, hedduu biyyoota)';
$string['settings:rerank_heading'] = 'RAG: Argannoo sadarkaa lama (re-ranking)';
$string['settings:rerank_heading_desc'] = 'Sadarkaa argannoo lammaffaa dirqiiti miti: wal-fakkaatinni cosine giddu-gala N-guddaa candidate chunks filacha (durtiin 50), ergasii re-ranker cross-encoder deewwaanis (gaaffii, chunk) pair hundaaf lakkoofsa kenna, K-guddaan caalmaa qaban promtitti seenan. Durtii cufaa; re-ranker qindaa\'amuu dhiisee ykn milkaa\'uu dhabee cosine sadarkaa tokkoo tokkoof deebi\'a.';
$string['settings:rerank_enabled'] = 'Argannoo sadarkaa lama (Voyage rerank-2.5)';
$string['settings:rerank_enabled_desc'] = 'Yeroo banaa ta\'u, argannoo RAG sadarkaa lama ta\'a: wal-fakkaatinni cosine candidate N-guddaa (durtiin 50) deebi\'a, ergasii Voyage rerank-2.5 cross-encoder deewwaanis lakkoofsa kenna K-guddaas promtitti seenan. Ol-guddinoota maxxanfaman: +15 Recall@10 dhaabbilee, +39% NDCG BEIR. ~$0.05/MTok kaffalti. <code>rerank_apikey</code> gadii barbaachisa; rerank milkaa\'uu dhiisee ykn qindaa\'uu dhabee cosine sadarkaa tokkotti deebi\'a.';
$string['settings:rerank_apikey'] = 'Rerank API key';
$string['settings:rerank_apikey_desc'] = 'Voyage AI API key rerank-2.5f. Duwwaa dhiisi key Embedding API Key olitti itti fayyadamuuf (Voyage kan baay\'ee qindaa\'ee tokkoo key tokko embed + rerank dambiif qoodate).';
$string['settings:rerank_model'] = 'Rerank model';
$string['settings:rerank_model_desc'] = 'Durtii <code>rerank-2.5</code>. Modeeliiwwan Voyage rerank haaraan asitti tarreeffamuu danda\'u.';
$string['settings:rerank_apibaseurl'] = 'Rerank API base URL';
$string['settings:rerank_apibaseurl_desc'] = 'Voyage rerank base URL overrideedi. Duwwaa dhiisi Embedding API Base URL olii ykn Voyage durtii (<code>https://api.voyageai.com/v1</code>) fayyadamuuf.';
$string['settings:rerank_candidates'] = 'Rerank candidate window';
$string['settings:rerank_candidates_desc'] = 'Kaadhimamtoota cosine top-N meeqni sadarkaa sirreeffamaatti galan. Duraan 20. Gaaffiiwwan 1,008 irratti safarame: 20 recall irratti 30 wal qixa (R@3 89.0% fi 89.3%) baasii harka sadaffaa gadi ta\'een, 50 immoo si\'a 2.5 baasii fudhata bu\'aa safaramu malee. 10 gadi recall ni hir\'ata. Baasiin gatii kanaan sarara qajeelaan dabala.';
$string['settings:stt_selfhosted_heading'] = 'Transcription ofiin-qabame (Whisper)';
$string['settings:stt_selfhosted_heading_desc'] = 'Sagalee gara barreeffamaatti jijjiiruun meeshaa keetii irra daqiiqaadhaan kaffaltii tokko malee hojjedhu. [[tutorshort]] gara server transcription OpenAI-waliin-wal-simatu kamiiyyuu qajeelchi: <code>whisper-server</code> Docker, <code>speaches</code> (faster-whisper), ykn <code>whisper.cpp</code> server. Server URL as qindaa\'ee yeroo karaa STT durtii ta\'a; Fornidarii kaffalaa Fornidarii STT banaa olitti filadhu overrideef. Server neetwoorkii dhuunfaa ykn plain http irra yoo ta\'e, host isaa SSRF trusted endpoints allowlistitti Kutaa Nageenyaa keessatti dabaluu yaadadhu.';
$string['settings:stt_selfhosted_url'] = 'Selfhosted STT server URL';
$string['settings:stt_selfhosted_url_desc'] = 'Server transcription OpenAI-waliin-wal-simatu base URL, fakkeenyaaf <code>http://10.0.0.5:8000</code>. [[tutorshort]] <code>/v1/audio/transcriptions</code> ofumaan dabalaa; karaa endpoint guutuu iyyuu fudhatama. Selfhosted STT danda\'amuu dhabuuf duwwaa dhiisi.';
$string['settings:stt_selfhosted_model'] = 'Selfhosted STT model';
$string['settings:stt_selfhosted_model_desc'] = 'Maqaa modeelii serveritti ergamu, Whisper model serverichi fe\'atee waliin walsimaa — fakkeenyaaf speachesf <code>Systran/faster-whisper-small</code> ykn <code>large-v3</code>. Serveroota ofiin-qabaman baay\'een fudhatan ykn muran <code>whisper-1</code> erguuf duwwaa dhiisi.';
$string['settings:stt_selfhosted_apikey'] = 'Selfhosted STT API key';
$string['settings:stt_selfhosted_apikey_desc'] = 'Dirqiiti miti. Serveroota ofiin-qabaman baay\'een neetwoorkii amansiifame duubatti key hin qaban; kana qofa serverichaatu bearer token barbaade yoo ta\'e qindi.';
$string['emergency:title'] = '[[tutorshort]] Qindaa\'inoota Yeroo Balaa';
