$string['email_unsubscribe:done_title'] = 'Galmee ba\'ame';
$string['email_unsubscribe:done_body'] = 'Xumurame — {$a->email} irraanfatoo gosa imeelii kanaa {$a->product} irraa hin fudhatu. Yaada kee yoo jijjiirte, galmeessa deebi\'sisuuf bulchaa {$a->product} gaafadhu, ykn fuula admin [[tutorshort]] Recipients dhaan filannoowwan galmeessuu haaraa ergadi.';
$string['email_unsubscribe:invalid_title'] = 'Liinkii galmee ba\'uu hin hojjetu';
$string['email_unsubscribe:invalid_body'] = 'Liinkiin galmee ba\'uu kun yeroon darbe ykn sirrii miti. Imeelii dhihoo nu irraa barbaadi, ykn harka bulchaa marsaatti kaasamu gaafadhu.';
$string['settings:prompt_proportions_heading'] = 'Proportions kutaa prompt (v5.6.0)';
$string['settings:prompt_proportions_heading_desc'] = 'Baajata system prompt gara kutaalee afuriitti qoodi: nageenyaa + eenyummaa, caasaa koorsii, qabiyyee koorsii, fi fuula ammaa. Miindaaleen % waligalan 100. Durtiileen safaraan (10 / 10 / 40 / 40) v5.6.0 qorannoo miindaa-arfii irraa dhufu; textarea duwwaa dhiisuun durtiileen sun fayyadamu. Ol-guddina ofumaa turn tokkoo tokkoo irratti fuuri addaa scope keessa jiraachuu irratti hundaa\'uun qoodiinsa sirreessa.';
$string['settings:prompt_section_weights'] = 'Miindaalee kutaa bu\'uuraa (JSON)';
$string['settings:prompt_section_weights_desc'] = 'JSON object dirqiiti miti kutaa tokkoo tokkoo % tti qindeessu. Durtiileen safaraman (10 / 10 / 40 / 40) fayyadamuuf duwwaa dhiisi. Fakkeenyaa: <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>. Miindaaleen waligalaan 100 ta\'uu qaban (±5%). <code>safety_identity</code> gadii 10% qaba jailbreak dide fi format markers yeroo hunda guutummaatti argamuu. <code>current_page + course_content</code> >=40% ta\'uu qaban modeelichi meeshaa guutuu qabaachuuf. Gatiileen daangaa keessaa alaa jiran durtiileen safaraman deebi\'u; admins prompt-debug log erga ol-qusatanii booda sakatta\'uun sirreessuu qaban.';
$string['settings:prompt_context_boost_mode'] = 'Garagalcha context boost';
$string['settings:prompt_context_boost_mode_desc'] = 'Sirreeffama ofumaa fuula-ammaa kutaalee miindaa qooduu turn fuuri addaa scope keessa jiru, qabiyyee koorsii fuuri hin filatamne yoo ta\'u. <strong>page_focus</strong> (durtii) dhaabbii 15 ol-guddeessa. <strong>aggressive</strong> 25 dhaabbii ol-guddeessa, barattonni yeroo hunda gaaffii fuuri-addaa gaafatan caalamaa. <strong>off</strong> ol-guddina cufaa; miindaaleen bu\'uuraa admin-qindeessame turn hundaaf ni hojjetan fuuri context osoo hin ilaallen.';
$string['settings:prompt_context_boost_off'] = 'Cufaa (miindaalee bu\'uuraa turn hundaaf fayyadami)';
$string['settings:prompt_context_boost_page_focus'] = 'Xiyyeeffannoo fuula (durtii, ~dhaabbii 15)';
$string['settings:prompt_context_boost_aggressive'] = 'Aggressive (~dhaabbii 25)';
$string['settings:prompt_section_weights_coach'] = 'Miindaalee coach-mode override (JSON, dirqiiti miti)';
$string['settings:prompt_section_weights_coach_desc'] = 'JSON object dirqiiti miti miindaalee kutaa bu\'uuraa addaan quiz coach mode keessatti (<code>quizmode=coach</code>) yeroo qofa overrideedi. Kutaa <code>current_page</code> caalmaatti qizota keessatti dabaluu barbaadde malee chat dansaa irratti dhiibbaa malee gaarii. Miindaalee bu\'uuraa dhaaluuf duwwaa dhiisi. Sirreeffaan walfakkaata qindaa\'inaa bu\'uuraa.';
$string['prompt_debug_view:title'] = 'Argii debug log prompt';
$string['prompt_debug_view:subtitle'] = 'System prompt walitti qabame + kutaa tokkoo tokkoo dhibduu + seenaa marii + ergaa fayyadamaa ammaa + metadata maxxanfamaa turn-tokkoo tokkoof, modeelichi akka isaan argetti. Kana kutaa qabiyyee fuula ammaa promtitti dhugaan galuu danda\'u mirkaneessuuf fi rakkoo qulqullina-deebii SSH serveritti seenanuu malee sakatta\'uuf fayyadami.';
$string['prompt_debug_view:disabled'] = 'Debug logging prompt ammallee CUFAA dha. Galmeessaa haaraa hin barreeffamu hanga banaamutti.';
$string['prompt_debug_view:enable_link'] = 'Qindaa\'inoota plugin bani "System prompt walitti qabame faayilaatti galmeessi" dandeessiisuuf.';
$string['prompt_debug_view:no_log_yet'] = 'Faayilii log hin jiru ammaaf. Debug log dandeessiiteen booda chat turn tokkoo ergi; faayiliin barreeffama jalqabaa irratti uumama.';
$string['prompt_debug_view:empty'] = 'Faayilii log jira garuu duwwaa dha. Chat turn ergi ergasii haaromsi.';
