$string['settings:mastery_classifier_provider'] = 'Fornidarii classifier';
$string['settings:mastery_classifier_provider_desc'] = 'Fornidarii id mastery classifier turn-tokkoo tokkoof fayyadamame. Fornidarii AI durtii dhaaluuf duwwaa dhiisi. Durtii <code>openai</code> fi modeelii classifier <code>gpt-4o-mini</code> gadii waliin wal-qabata — filannoo TIER 1 baasii gadii caalu structured-output classification (~$220/ji\'a ol-qusachuu 100k MAU vs chat tier). Yeroo qindaa\'u, tarree Fornidariiwwan Wal-bira-qabamuun fornidarii id kana qabu API key, base URL, fi temperature dhiyeessa.';
$string['settings:premium_escalation_heading'] = 'Sadarkaa ol-guddina premium (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'Routing hanga modeelii premium (Claude Opus 4.8 durtiidhaan) gara promtootaatti yeroo chat tier hojjetaa ol-guddinaan hin dandeenye — yeroo baay\'ee math sadarkaa lama, CS, fi saayinsii. 2026-06-09 A.10 bake-off: Opus 4.8 14.97/15 vs gpt-4o dha 12.68/15 promtoota jabaatan irratti mo\'ate. Karaalee trigger lama: regex match ergaa fayyadamaa irra, YKN allowlist koorsii turn hundaaf ol-guddeessa. Durtii cufaa. ~5% ol-guddina, ~$700/ji\'aa 100k [[unishort]] MAU irratti baasii chat bu\'uuraa irra.';
$string['settings:premium_escalation_enabled'] = 'Routing ol-guddina premium dandeessisi';
$string['settings:premium_escalation_enabled_desc'] = 'Yeroo banaa ta\'u, router turn-tokkoo tokkoo trigger regex fi allowlist koorsii bilbila chat hundaaf sakatta\'a; turn walsimantu fornidarii premium keessa darbama. Tarreen premium dhabuu ykn uumamuu dhabuu yoo ta\'e fornidariitti hojjetaatti deebi\'a. Override admin-LLM-picker yeroo hunda mo\'a.';
$string['settings:premium_escalation_provider'] = 'Fornidarii premium';
$string['settings:premium_escalation_provider_desc'] = 'Fornidarii id bilbiloota premium dhaan karooressuu. Tarree Fornidariiwwan Wal-bira-qabamuu (kanaaf API key, base URL, fi temperature bakka tokko bulchaa admin irraa dhufan) waliin walsimuu qaba. Durtii <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'Modeelii premium';
$string['settings:premium_escalation_model_desc'] = 'Maqaa modeelii fornidarii premiuumitti ergamu. Durtii <code>claude-sonnet-5</code> murtoo A.10 bake-off irratti hundaa\'uun.';
$string['settings:premium_escalation_triggers'] = 'Regex trigger premium';
$string['settings:premium_escalation_triggers_desc'] = 'PCRE regex tokkoo tokkoo sarara tokkotti (delimiter malee; walsimsiisuun case-insensitive ofumaan hojjetama). Sarara # dhaan jalqaban yaada. Durtii STEM markers A.10 bake-off irraa guruurame fayyadamuuf duwwaa dhiisi ("derive", "prove that", "step by step", math LaTeX, code blocks fenced, big-O, waltaantoota, optimization, fi kkf).';
$string['settings:premium_escalation_course_tags'] = 'Allowlist koorsii premium';
$string['settings:premium_escalation_course_tags_desc'] = 'Koorsii shortname ykn idnumber prefix tokkoo tokkoo sarara tokkotti. Turn hundinuu koorsii walsimu keessatti regex ergaa osoo hin jaalin ofumaan ol-guddeessa (koorsii STEM-hedduu itti fayyadami, ol-guddinnni durtii ta\'uu qabdu). Walsimuun prefix case-insensitive — "MATH" MATH121, MATH205, kkf walsimsiisuun.';
$string['settings:spend_cap_per_course_default'] = 'Cap baasii koorsii-tokkoo durtii (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'Cap eeggannoo koorsii hundaaf cap baasii koorsii-tokkoo ofii qindaa\'ee hin qabnetti hojjetama. Fakkeenyaaf <code>30</code> qindi koorsii tokkoo baasii ji\'aatti $30 irratti daangessuu koorsii tokko tokko sirreessuu malee. <code>0</code> = durtii hin jiru (cap marsaa guutuu fi koorsii-tokkoo-override qofa hojjeta). Koorsii 80% / 95% / 100% cap kanaa darbe, pipeline beeksisa spend-guard jirtu ergaa admin beeksisa ergiti (tarree fudhataa: <code>spend_notify_emails</code>, bulchaa marsaatti deebi\'uun). Koorsii addaa daangaa ofii ol ta\'e yeroo hunda override ol-qindaa\'inaan ceil isaa guddisuu danda\'a.';
$string['settings:cost_anomaly_heading'] = 'Argitee gatii al-dansaa (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'Hojii qindaa\'uu guyyaa guyyaa (<code>cost_anomaly_check</code>) baasii [[tutorshort]] marsaa marsaa guyyaa har\'aa median rolling 7-guyyaa waliin wal-bira qabu. Tarree fudhataa <code>spend_notify_emails</code> imeelii ergiti (bulchaa marsaatti deebi\'uun) guyyaa har\'aa multiplier × median qaqqabe yeroo. Garagalchi sadii dhaabbiiwwan 80% / 95% / 100% spend-cap daangaa jiran: (1) koorsii dadhabiinsa koorsii tokkoo ol-guddina isaa dhaala ceiling dhufuu dhabee baay\'oo guddaa, (2) dandeessisuu sadarkaa premium doo\'amiinsa, (3) fornidarii misroute. Durtii cufaa; walfakkaata [[tutorshort]] keessaa gaaffii Redash <code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code> irratti.';
$string['settings:cost_anomaly_enabled'] = 'Argitee gatii al-dansaa dandeessisi';
$string['settings:cost_anomaly_enabled_desc'] = 'Yeroo banaa ta\'u, hojiin qindaa\'uu guyyaa baasii guyyaa har\'aa median rolling 7-guyyaa waliin sakatta\'a, al-dansaa irratti bulchaa beeksisa. Guyyaalee 7 jalqabaa erga dandeessisee status <code>insufficient_history</code> (seenaa bu\'uuraa hin jiru ammaaf) agarsiisu, beeksisa tokkollee hin ergitu. Guyyaa tokko tokkoof idhoos: kaayyoo <code>config_plugins</code> keessatti imeelii irra-irra deebi\'uu cron yoo irra deebi\'e dhaabsisa.';
$string['settings:cost_anomaly_multiplier'] = 'Multiplier al-dansaa';
$string['settings:cost_anomaly_multiplier_desc'] = 'Baasii guyyaa har\'aa multiplier × median 7-guyyaa caalee beeksisa mul\'isu qaba. Durtii <code>2.0</code>. Gara <code>1.5</code> xiqqeessi beeksisa duraa (erga yoo baay\'atan yeroo galma\'ina). Gara <code>3.0</code> ol-guddisi [[unishort]] fayyadamaan al-dansaa 2x dansaa ta\'e yoo ta\'e.';
$string['task:cost_anomaly_check'] = 'Sakatta\'iinsa [[tutorshort]] al-dansaa gatii (guyyaa guyyaa)';

// v6.4.0 signed policy bundle strings (added 2026-06-11).
$string['settings:policy_bundle_heading'] = 'Signed policy bundle (update amala fagoo irraa)';
$string['settings:policy_bundle_heading_desc'] = 'Qindaa\'inawwan amala (prompts, routing, escalation triggers, RAG tuning, spend policy) faayila JSON signed cryptographically irraa code deploy malee fayyadami. Hojii daily scheduled bundle URL fiddi, mallatoo Ed25519 isaa public key armaan gadii waliin mirkaneessa, qindaa\'inawwannis key hunduu allowlist keessa yoo jiraate fi version bundle kan dhumaa caalaa haaraa yoo ta\'e qofa hojii irra oolcha. API keys, URLs, webhooks, fi qindaa\'inawwan nageenya bundle tiin yeroo kamiiyyuu qindeeffamuu hin danda\'an. Bundles <code>admin/cli/policy_bundle_tool.php</code> (keygen, sign, verify, status, sync) waliin uumi fi mallattoo goodi.';
$string['settings:policy_bundle_enabled'] = 'Policy bundle sync dandeessisi';
$string['settings:policy_bundle_enabled_desc'] = 'Yoo dandeessifame, hojiin guyyaa guyyaa signed bundles fiddi fi hojii irra oolcha. Dura bu\'uuraatti cufaa dha. Dhaabuu sync hunda hatattamaan dhaaba; qindaa\'inawwan dursanii hojii irra oolfaman gatii isaanii eegu.';
$string['settings:policy_bundle_url'] = 'Policy bundle URL';
$string['settings:policy_bundle_url_desc'] = 'HTTPS URL JSON bundle signed (fakkeenyaaf S3 object yookiin GitHub raw URL). URL SSRF validation wal fakkaataa AI provider endpoints waliin darba; private-network yookiin plain-http hosts SSRF trusted endpoints allowlist keessatti galii barbaadu.';
$string['settings:policy_bundle_pubkey'] = 'Policy bundle public key';
$string['settings:policy_bundle_pubkey_desc'] = 'Base64 Ed25519 public key bundle signatures mirkaneessuuf fayyadamu. Keypair <code>policy_bundle_tool.php --keygen</code> waliin uumi; private key qopheessaa bundle waliin taa\'a, iddoo kamiiyyuu fe\'amuu hin qabu.';
$string['settings:policy_bundle_status'] = 'Sync dhumaa';
$string['settings:policy_bundle_applied_version'] = 'version hojii irra oolfame';
$string['task:policy_bundle_sync'] = '[[tutorshort]] signed policy bundle sync';
$string['policy_bundle:invalid'] = 'Policy bundle dide: {$a}';
$string['prompt_debug_view:retrieved_chunks'] = 'Kutaalee argaman (filannoo RAG)';
$string['prompt_debug_view:retrieved_chunks_hint'] = 'Caqasoota retriever gaaffii kanaaf filate, sajoo wal-simannaa isaaniitii fi madda (cmid) waliin tartiiba sadarkaatiin. Akka moodeelichi qabiyyee koorsii baayʼee wal-simu argate mirkaneeffachuuf kana fayyadami.';
$string['settings:avatar_animation_enabled'] = 'Sochii avatar';
$string['settings:avatar_animation_enabled_desc'] = 'Avatar SVG uumame sochoosu: yeroo boqonnaa ijaan diriiruu, akkasumas sochiiwwan afaanii sagalee barreeffama-gara-sagaleetti walmakame yeroo gargaaraan dubbatu. Filannoo sochiiwwan hir\'atame meeshaa barataa kabaja. Qabiyyee tokkoo tokkoon sadarkaa A/B mirkaneessuuf: gatii qindaa\'ina avatar_animation_course_COURSEID 0 ykn 1 godhaa.';
