$string['radar_report:print'] = 'Maxxansi / akka PDF olkaa\'i';
$string['radar_report:generated'] = '{$a} irratti uumame';
$string['radar_report:query'] = 'Gaaffii';
$string['radar_report:response'] = 'Deebii';
$string['radar_report:privacy_note'] = 'Ragaan barattootaa hundi gabaasa kana keessa jiru maqaa dhabeessa taasifameera. Uummataaf hin qoodin.';

$string['settings:hidden_categories'] = 'Ramaddiiwwan koorsii dhokataniiru';
$string['settings:hidden_categories_desc'] = 'Tarreeffama maqaalee yookaan eenyummeessaa ramaddiiwwan koorsii, qoodduudhaan adda baafame, iddoo gargaaraan mul\'achuu hin qabne. Fakkeenya: "Guddina koorsii, 42". Yeroo haalli gulaallii banaa ta\'es gargaaraan ofumaan dhokata.';
$string['settings:provider_heading'] = 'Dhiyeessaa AI fi haasawa';
$string['settings:provider_heading_desc'] = 'Waltajjii AI, moodela, fi amala haasawaa qindeessi.';
$string['settings:claude_temperature_allow_prefixes'] = 'Moodelawwan Claude kanneen ulaagaa temperature deeggaran';
$string['settings:claude_temperature_allow_prefixes_desc'] = 'Sararaa tokkotti durduubee maqaa moodelaa tokko. Moodelawwan Anthropic maqaan isaanii isaan kana keessaa tokkoon jalqabu ammas ulaagaa fakkeenya fudhannaa <code>temperature</code> fudhatan. Moodela Claude kamiyyuu durduubee kamiifis walsimuu dhabuuf, temperature dhiifamaa (moodelawwan sammuu qayyabannoo Opus 4.7 irraa jalqabanii dogoggora HTTP 400 waliin didan). Gatii durtii ida\'ama waliin dhufe fayyadamuuf duwwaa dhiisi.';
$string['settings:max_tokens'] = 'Dheerina deebii ol\'aanaa (tokens)';
$string['settings:max_tokens_desc'] = 'Baay\'ina tokens ol\'aanaa deebii AI tokkoof. Gatiiwwan gadi aanaan deebii gabaabaa fi saffisaa kennan. 512 = tilmaamaan hima 2-3, 1024 = tilmaamaan keeyyata 1-2, 2048 = ibsa dheeraa. Daangaa hin barbaachisu yoo taate 0 kaa\'i (gatiin durtii dhiyeessaa hojjeta).';
$string['settings:profile_update_interval'] = 'Yeroo haaromsa piroofaayilii barataa';
$string['settings:profile_update_interval_desc'] = 'Erga barataa irraa ergaawwan hanga kana koorsii keessatti dhufanii booda, gargaaraan piroofaayilii barnootaa cimina, laafina, akkaataa barnootaa, fi fedhii cuunfu ijaara (yookaan haaromsa). Deebiiwwan dhuunfaaf piroofaayiliin kun gaaffii sirnaa keessatti galcha. Cufuuf 0 kaa\'i. Durtii: 10.';
$string['settings:enable_thinking'] = 'Yaaduu babal\'ate (Claude qofa)';
$string['settings:enable_thinking_desc'] = 'Moodelawwan Claude\'f yaaduu of madaalu banaa taasisa. Claude ofii isaa yeroo fi hangam rakkoo tokko irratti yaaduu isaa osoo deebii hin kennin dura murteessa. Gaaffiiwwan walxaxaa irratti sirrummaa fooyyessa, garuu fayyadama tokens fi turmaata dabala. Qabiyyeen yaadaa barattootaaf hin agarsiifamu. Dhiyeessitoonni kaan qindaa\'ina kana tuffatan.';
$string['settings:rag_sources_heading'] = 'Madda qabiyyee RAG';
$string['settings:rag_sources_heading_desc'] = 'Gosoota qabiyyee koorsii kamiin keessaa barreeffama akka baasu tarreessaan RAG filadhu. Agarsiistonni haala <a href="{$a}">fuula bulchiinsa RAG</a> irra jiran, baasaan tokkoon tokkoon isaa hojjechuuf waan barbaachisu qabaachuu isaa agarsiisan (fakkeenyaaf meeshaa pdftotext yookaan tarreeffama hayyama Cloudflare).';
$string['settings:rag_extract_pdf'] = 'Faayiloota PDF tarreessi (mod_resource)';
$string['settings:rag_extract_pdf_desc'] = 'Meeshaa <code>pdftotext</code> (poppler) fayyadamuudhaan faayiloota PDF olkaa\'aman keessaa barreeffama baasa. Karaan meeshaa ofumaan argama; yoo barbaachise gadi ibsi.';
$string['settings:rag_pdftotext_path'] = 'Karaa meeshaa pdftotext';
$string['settings:rag_pdftotext_path_desc'] = 'Ofumaan argamuuf duwwaa dhiisi (<code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code> fi <code>which pdftotext</code> ilaalama). Sirni ijaarsa keessan bakka biraa yoo jiraate qofa guuti.';
$string['settings:rag_extract_docx'] = 'Faayiloota DOCX tarreessi (mod_resource)';
$string['settings:rag_extract_docx_desc'] = 'ZipArchive PHP fayyadamuudhaan sanadoota Word olkaa\'aman keessaa barreeffama baasa. Irkoo alaa hin barbaachisu.';
$string['settings:rag_extract_pptx'] = 'Faayiloota PPTX tarreessi (mod_resource)';
$string['settings:rag_extract_pptx_desc'] = 'ZipArchive PHP fayyadamuudhaan dhiyeessiiwwan PowerPoint ammayyaa olkaa\'aman keessaa barreeffama baasa. XML saaliidii fi yaadannoo dubbataa akkaataa tartiiba saaliidiitiin ilaala; irkoo alaa hin barbaachisu. Faayilonni biinarii duraanii <code>.ppt</code> hin deeggaramne — dhiyeessiiwwan sana akka <code>.pptx</code> irra deebi\'ii olkaa\'i.';
$string['settings:rag_extract_h5p'] = 'Qabiyyee H5P tarreessi (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'JSON qabiyyee H5P keessa deema, dirreewwan barreeffama qaban hunda tarreessa (gaaffii, deebii, yaada deebii, ibsa). Meetaadaataan gosoota qabiyyee H5P bal\'aa dha; haalota daangaa irratti walsimannaa dogoggoraa muraasni ni eegama.';
$string['settings:rag_extract_scorm'] = 'Paakejii SCORM tarreessi (mod_scorm)';
$string['settings:rag_extract_scorm_desc'] = 'Paakejii SCORM bana, <code>imsmanifest.xml</code>, faayiloota <code>.html</code> hunda, fi sarara qabiyyee Articulate Storyline tarreessa. Adeemsi SCORM gatii guddaa qabaachuu waan danda\'uuf <strong>durtiidhaan cufameera</strong>. Guddina paakejii ol\'aanaa <code>rag_scorm_max_mb</code> murteessa.';
$string['settings:rag_scorm_max_mb'] = 'Guddina paakejii SCORM ol\'aanaa tarreeffamu (MB)';
$string['settings:rag_scorm_max_mb_desc'] = 'Fayyadama yaadannoo hedduu oolchuuf paakejii SCORM gatii kanaa caalaa guddaa ta\'e darba.';
$string['settings:rag_fetch_transcripts'] = 'Barreeffama sagalee viidiyoo fi qabiyyee walqunnamsiisaa keessa galfamaniif fidi';
$string['settings:rag_fetch_transcripts_desc'] = 'Qabiyyee mod_page fi mod_book iframe keessa galfaman (Synthesia, YouTube, Articulate, Genially) barbaaduuf sakatta\'a, teessoo barreeffama sagalee galcha tokkoon tokkoon isaa waliin dhufe fida (gubbaa fi jala kaaddiraa barbaada). Waliigaltee HTTPS ba\'aa sarvarii kana irraa gara keessummeessaa barreeffama sagaleetti barbaachisa. <strong>Durtiidhaan cufameera</strong>; dhiyeessaan barreeffama sagalee sarvarii kana tarreeffama hayyama isaa keessatti erga dabale booda bani (fakkeenyaaf seera Cloudflare IP irratti hundaa\'e).';
$string['settings:rag_iframe_host_patterns'] = 'Bocawwan keessummeessaa iframe';
$string['settings:rag_iframe_host_patterns_desc'] = 'Sararaa tokkotti ibsa idilee tokko, amala <code>src</code> iframe waliin walsimsiisama. Kaaddirri walsimu tokkoon tokkoon isaa akka galcha walqunnamsiisaa barreeffamni sagalee isaa walitti hidhamee tarreeffamuu qabu ilaalama. Sararoonni <code>#</code>\'n jalqaban yaada dha.';
$string['settings:rag_transcript_url_pattern'] = 'Boca teessoo barreeffama sagalee';
$string['settings:rag_transcript_url_pattern_desc'] = 'Ibsa idilee teessoo hidhaawwan barreeffama sagalee waliin walsimu. Iframe tokkoon tokkoon argameef, tarreessaan hidhaa walsimu dhiyoo jiru (gubbaa yookaan jala isaa) filatee lamaan walitti hidha. Walitti hidhuu barreeffama sagalee cufuuf duwwaa dhiisi.';
$string['settings:performance_heading'] = 'Raawwii';
$string['settings:performance_heading_desc'] = 'Hangam qabiyyeen koorsii gaaffii AI keessatti akka galu to\'ata. Gatiiwwan gadi aanaan deebii saffisaa jechuu dha garuu haala qabiyyee AI\'f xiqqoo ta\'a.';
$string['settings:max_content_per_resource'] = 'Qabiyyee ol\'aanaa madda tokkoof (arfiiwwan)';
$string['settings:max_content_per_resource_desc'] = 'Baay\'ina arfiiwwan qabiyyee ol\'aanaa fuula yookaan boqonnaa kitaabaa tokkoon tokkoon isaa irraa baafamu. Gatiiwwan gadi aanaan guddina gaaffii hir\'isu, deebiis saffisiisu.';
$string['settings:max_total_content'] = 'Qabiyyee waliigalaa ol\'aanaa (arfiiwwan)';
$string['settings:max_total_content_desc'] = 'Baay\'ina arfiiwwan qabiyyee koorsii waliigalaa ol\'aanaa gaaffii sirnaa keessatti galu. Gatiiwwan gadi aanaan guddina gaaffii hir\'isu, deebiis saffisiisu.';
$string['settings:spend_guard_heading'] = 'Eegumsa baasii fi fooyyessaa';
$string['settings:spend_guard_heading_desc'] = 'Yeroo tokkoon tokkoon isaatti daangaa baasii LLM kaa\'i. Yeroo daangaan ga\'u, [[tutorshort]] gaaffiiwwan dhaaba yookaan gara dhiyeessaa gatii xiqqaa foddaa bakka bu\'aa keessan jiruutti jijjiira. Haala baasii ammaa fi yaada fooyyessaa argachuuf <a href="{$a}">fuula gatii tokens</a> ilaali.';
$string['settings:spend_cap_period'] = 'Yeroo daangaa baasii';
$string['settings:spend_cap_period_desc'] = 'Daangaan baasii yeroo hangam irra deebi\'ee kaa\'ama. Kalaandarii waliin walsima: ji\'aan guyyaa 1ffaa, torbaniin Wiixata, guyyuun halkan walakkaa jalqaba.';
$string['settings:spend_cap_site'] = 'Daangaa baasii marsariitii guutuu (USD)';
$string['settings:spend_cap_site_desc'] = 'Daangaa walitti qabaa USD\'n koorsiiwwan fi dandeettiiwwan hundaaf yeroo ammaa keessatti. <code>0</code> = daangaa hin qabu. Daangaawwan dandeettii tokkoon tokkoon gadi jiran yoo kaa\'aman dursa argatan.';
$string['settings:spend_cap_chat'] = 'Daangaa haasawaa (USD)';
$string['settings:spend_cap_chat_desc'] = 'Daangaa haasawaa fi qormaata barattootaaf qofa. <code>0</code> = daangaan marsariitii guutuu fayyadama.';
$string['settings:spend_cap_voice'] = 'Daangaa sagalee (USD)';
$string['settings:spend_cap_voice_desc'] = 'Daangaa sagaleef (Realtime + TTS + STT). Sagaleen yeroo baay\'ee baasii guddaa dha — duraan daangessi.';
$string['settings:spend_cap_rag'] = 'Daangaa RAG (USD)';
$string['settings:spend_cap_rag_desc'] = 'Daangaa waamicha embedding yeroo koorsiiwwan tarreeffamanitti raawwatamuuf.';
$string['settings:spend_cap_analytics'] = 'Daangaa xiinxalaa (USD)';
$string['settings:spend_cap_analytics_desc'] = 'Daangaa gaaffiiwwan Learning Radar bulchitootaaf.';
$string['settings:spend_failover_chain'] = 'Foddaa bakka bu\'aa';
$string['settings:spend_failover_chain_desc'] = 'Yeroo daangaan ga\'u, [[tutorshort]] dhiyeessitoota kanneen tartiibaan yaala. Sararaa tokkotti galcha tokko, bocaan <code>capability:label</code>. Asxaawwan galchaawwan Dhiyeessitoota walbira qabiinsaa (<code>chat</code> / <code>analytics</code>\'f) yookaan Dhiyeessitoota sagalee (<code>voice</code>\'f) keessa jiran agarsiisan. Sararoonni <code>#</code>\'n jalqaban yaada dha. Fakkeenya:<br><code>chat:claude-haiku<br>chat:ollama-local<br>voice:openai-prod<br>analytics:deepseek</code>';
$string['settings:failover_per_call_enabled'] = 'Waamicha tokkoon tokkoon isaatti gara bakka bu\'aatti jijjiiruu (v5.5.0)';
$string['settings:failover_per_call_enabled_desc'] = 'Yeroo banaa ta\'u, waamichi haasawaa tokkoon tokkoon isaa dhiyeessaa duraa haguuggii foddaa bakka bu\'aa keessatti maranaa. Yoo waamicha tokko keessatti yeroon dhume yookaan dogoggorri 5xx uumame, [[tutorshort]] gara galcha itti aanu <strong>foddaa bakka bu\'aa</strong> gubbaa jiruutti jijjiira, dhiyeessaa kufeef daawwii daqiiqaa 15 bana. Jijjiirraan tokkoon tokkoon isaa sarara qorannoo barreessa (<code>failover_fallthrough</code>); erga bantee booda foddaan hojjechaa jiraachuu mirkaneessuuf Bulchiinsa -> [[tutorshort]] -> Galmee qorannoo ilaali. Durtiidhaan cufameera; foddaan erga mirkanaa\'ee fi dhaabbanni keessan waliigalteewwan adeemsa daataa barbaachisan dhiyeessaa foddaa keessa jiru tokkoon tokkoon isaaf jiraachuu erga mirkaneessee booda qofa bani.';
$string['settings:failover_timeout_chat'] = 'Bakka bu\'aa: yeroo eegumsa haasawaa (sekondii)';
$string['settings:failover_timeout_chat_desc'] = 'Osoo hin jijjiirin dura token jalqabaa dhiyeessaa haasawaa irraa hangam eeguu. Durtii sekondii 8. Gatiiwwan gadi aanaan dhiyeessitoota suuta ta\'an irraa saffisaan fagaatan, bakka isaatti gaaffiiwwan yeroof suuta ta\'an irratti akeekkachiisa sobaa dabalan; gatiiwwan ol\'aanaan foddaa dhiyeessaa duraa biratti yeroo dheeraaf qaban. <strong>Waamicha tokkoon tokkoon isaatti gara bakka bu\'aatti jijjiiruu</strong> yeroo banaa ta\'e qofa ilaalama.';
$string['settings:spend_notify_emails'] = 'Fudhattoota akeekkachiisa baasii';
$string['settings:spend_notify_emails_desc'] = 'Teessoowwan imeelii qoodduudhaan adda baafaman, daangaa 80%, 95%, fi 100% irratti beeksisni ni ergamaaf. Bulchitoota marsariitii hunda beeksisuuf duwwaa dhiisi.';
$string['settings:opt_cost_weight'] = 'Fooyyessaa: ulfaatina gatii';
$string['settings:opt_cost_weight_desc'] = 'Fooyyessaan dhiyeessitoota yeroo sadarkaa kennuutti gatii hangam ilaala. 0.0 gatii tuffata, 1.0 gatii qofaan fooyyessa. Ulfaatina qulqullina waliin madaalama.';
$string['settings:opt_quality_weight'] = 'Fooyyessaa: ulfaatina qulqullina';
$string['settings:opt_quality_weight_desc'] = 'Fooyyessaan dhiyeessitoota yeroo sadarkaa kennuutti quufa barataa (harka sadarkaa gaarii) hangam ilaala. 0.0 qulqullina tuffata.';
$string['settings:inactivity_reminder_enabled'] = 'Yaadachiisa sochii dhabuu';
$string['settings:inactivity_reminder_enabled_desc'] = 'Barattoota baay\'ina guyyoota qindaa\'e keessatti koorsii isaanii hin banneef imeelii torbanii erga.';
$string['settings:inactivity_threshold_days'] = 'Daangaa sochii dhabuu (guyyoota)';
$string['settings:inactivity_threshold_days_desc'] = 'Osoo imeeliin yaadachiisaa hin ergamin dura guyyoonni sochii dhabuu meeqa.';
$string['settings:voice_providers_heading'] = 'Dhiyeessitoota sagalee (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'Dhiyeessaa API sagalee tokko yookaan caalaa qindeessi. Qindaa\'inoonni kun dhiyeessaa haasawaa gubbaa jiru fi dhiyeessaa embedding RAG irraa walaba dha — sagaleen tarreeffama dhiyeessitoota ofii isaa qaba, sababiin isaas amma OpenAI fi xAI qofti gabaa Realtime WebSocket irratti hundaa\'e, TTS, fi STT dhiyeessan. Dhiyeessaan galmaa\'e kamiin dandeettii tokkoon tokkoon isaa akka qabatu tarreeffamoota gadii irraa filadhu. Yoo sarari kamiyyuu hin ibsamne, amalli furtuu tokkoo duraanii hojjeta (furtuu API Realtime gubbaa jiru yookaan furtuu OpenAI guddaa). Marsariitiin haasawaaf Together AI / Anthropic / DeepSeek / Gemini / Mistral fayyadamu sagaleen akka hojjetuuf asitti yoo xiqqaate sarara tokko qindeessuu qaba.';
$string['settings:voice_active_realtime'] = 'Dhiyeessaa Realtime hojjetu';
$string['settings:voice_active_realtime_desc'] = 'Dhiyeessaan sagalee qindaa\'e kamiin marsaawwan ergamaa sagalee Realtime qabata.';
$string['settings:voice_active_tts'] = 'Dhiyeessaa TTS hojjetu';
$string['settings:voice_active_tts_desc'] = 'Dhiyeessaan sagalee qindaa\'e kamiin deebii AI sagalee guddaan dubbisa.';
$string['settings:voice_active_stt'] = 'Dhiyeessaa STT hojjetu';
$string['settings:voice_active_stt_desc'] = 'Dhiyeessaan kamiin dubbii barataa gara barreeffamaatti jijjiira. Yoo gadi qindaa\'e sarvarii Whisper ofii keessan dursaan fayyadamuuf, achiis sarara jalqabaa dhiyeessitoota sagalee yookaan furtuu duraanii fayyadamuuf duwwaa dhiisi.';
$string['settings:stt_selfhosted_enabled'] = 'Barreeffama dubbii sarvarii ofii irratti bani';
$string['settings:stt_selfhosted_enabled_desc'] = 'Galtee sagalee fi Soapbox\'f karaa dubbii gara barreeffamaatti jijjiiruu akka ta\'u sarvarii Whisper ofii gadi jiru fayyadama. Gadi teessoo sarvarii barbaachisa. Yeroo cufamu, teessoon yoo kaa\'ames barreeffamni dubbii gara karaa keessummeessame (OpenAI Whisper) yookaan karaa biraawzariitti deebi\'a.';
$string['settings:stt_selfhosted_warm'] = 'Yeroo waraabbiin Soapbox jalqabu ho\'isi';
$string['settings:stt_selfhosted_warm_desc'] = 'Yeroo banaa ta\'u, waraabbii Soapbox jalqabuun gaaffii "ho\'isuu" salphaa (hanga danda\'ametti) gara sarvarii barreeffama dubbii ofiitti erga, kanaaf keessummeessaan gara zeeroo hir\'atu (fakkeenyaaf Cloud Run) yeroo barataan ammas waraabaa jirutti ka\'uu danda\'a — kanaan turmaanni jalqabaa qorraa yeroo dhiyeessii keessatti barreeffama dubbii hojjetu irraa dhokataa ta\'a. Yoo teessoon sarvarii ofii gubbaatti hin kaa\'amne dhiibbaa hin qabu. Durtiidhaan cufameera.';
$string['settings:voice_tab_enabled'] = 'Caancala Sagalee bani';
$string['settings:voice_tab_enabled_desc'] = 'Caancala Sagalee sarara qajeelfamaa gadii irratti agarsiisa. Yeroo cufamu, barattoonni caancaloota Haasawaa fi Yaadannoo qofa argan. Dandeettiiwwan sagalee (shaakala haasawaa, shaakala jecha dubbisuu) adda banaman yoo ta\'an gaaffiiwwan jalqaba haasawaa karaa argamuu itti fufan.';
$string['settings:soapbox_heading'] = 'Soapbox';
$string['settings:soapbox_heading_desc'] = 'Shaakala dhiyeessii afaanii: waraabbiiwwan akkamitti barreeffamatti jijjiiramanii fi safartuu kamiin qabxii kennamuuf. Soapbox koorsii tokkoon tokkoon isaaf gulantaa Soapbox kutaa Barsiisuu keessa jiruun bani.';
$string['settings:soapbox_max_seconds'] = 'Dheerina waraabbii Soapbox ol\'aanaa (sekondii)';
$string['settings:soapbox_max_seconds_desc'] = 'Daangaa gubbaa guutuu dheerina waraabbii hojii kamiifis. Barsiisonni daangaa gabaabaa kaa\'uu danda\'an. Durtii 720 (daqiiqaa 12).';
$string['settings:soapbox_max_recordings'] = 'Waraabbii Soapbox ol\'aanaa barataa fi hojii tokkoon tokkoon';
$string['settings:soapbox_max_recordings_desc'] = 'Daangaa gubbaa guutuu baay\'ina waraabbii barataan tokko hojii tokkoof gochuu danda\'u, qindaa\'ina yaaliiwwan hojii tokkoon tokkoon isaa hin ilaalin. Durtii 3.';
$string['settings:soapbox_retention_days'] = 'Yeroo kuusaa waraabbii Soapbox (guyyoota)';
$string['settings:soapbox_retention_days_desc'] = 'Osoo ofumaan hin haqamin dura waraabbiin hangam kuufama; barreeffamni dubbii, qabxiin, fi yaadni deebii ni turan. Guyyoota 1–28 gidduutti daangeffama. Daataa hir\'isuuf hanga gabaabaa ta\'e caalaa gaarii dha. Durtii 7.';
$string['settings:soapbox_video_quality'] = 'Qulqullina viidiyoo Soapbox';
$string['settings:soapbox_video_quality_desc'] = 'Ifummaa fi saffisa biitii waraabbii. Kun sababa guddaa gatii fi bal\'ina hidhannoo ti; dubbataan haala giddu galeessaan waraabame qulqullina idileetiinis ifatti mul\'ata. Qulqullinni gadi aanaa hidhannoo laafaaf mala; qulqullinni ol\'aanaan yeroo bal\'inni mul\'inaa barbaachisu qofa.';
$string['settings:soapbox_storage_bucket'] = 'Baaketii kuusaa Soapbox';
$string['settings:soapbox_storage_bucket_desc'] = 'Baaketii S3 waraabbiif. Durtii: baaketii kuusaa waliin qooddatan.';
$string['settings:soapbox_storage_region'] = 'Naannoo kuusaa Soapbox';
$string['settings:soapbox_storage_region_desc'] = 'Naannoo AWS baaketii, fakkeenyaaf us-east-1.';
$string['settings:soapbox_storage_prefix'] = 'Durduubee furtuu kuusaa Soapbox';
$string['settings:soapbox_storage_prefix_desc'] = 'Durduubee furtuuwwan baaketii keessaa. Seerri marsaa jireenyaa isaan xiyyeeffachuu akka danda\'uuf waraabbiiwwan karaa kana jala kuufamu.';
$string['settings:soapbox_storage_key'] = 'Eenyummeessaa furtuu argannoo kuusaa Soapbox';
$string['settings:soapbox_storage_key_desc'] = 'Eenyummeessaa furtuu argannoo qooda fudhataa IAM durduubee gubbaa irratti PutObject/GetObject/DeleteObject\'tti daangeffame.';
$string['settings:soapbox_storage_secret'] = 'Furtuu argannoo iccitii kuusaa Soapbox';
$string['settings:soapbox_storage_secret_desc'] = 'Furtuu argannoo iccitii eenyummeessaa furtuu argannoo gubbaa waliin walsimu.';
$string['settings:survey_heading'] = 'Qorannoo barattootaa';
$string['settings:survey_heading_desc'] = 'Qorannoo muuxannoo barataa haasawaa keessa jiru qindeessi. <a href="{$a}" class="btn btn-sm btn-outline-primary ml-2">Gaaffiiwwan qorannoo gulaali &rarr;</a>';
$string['settings:survey_enabled'] = 'Qorannoowwan bani';
$string['settings:survey_enabled_desc'] = 'Yeroo banaa ta\'u, barattoonni muuxannoo isaanii barsiisaa AI waliin qabaniif qorannoo guutuu akka danda\'an gaafatamu.';
$string['settings:survey_trigger_messages'] = 'Erga ergaawwan N booda agarsiisi';
$string['settings:survey_trigger_messages_desc'] = 'Erga barataan koorsii keessatti ergaawwan hanga kana ergee booda affeerraa qorannoo agarsiisa. Harkaan yeroo kaafamu qofa agarsiisuuf 0 kaa\'i.';
$string['settings:survey_frequency'] = 'Yeroo baay\'ina qorannoo fayyadamaa tokkoon tokkoon';
$string['settings:survey_frequency_desc'] = 'Koorsii tokkoon tokkoon keessatti barataan tokko qorannoo guutuuf yeroo hangam affeeramuu danda\'a.';
$string['settings:rubric_heading'] = 'Safartuuwwan shaakalaa';
$string['settings:rubric_heading_desc'] = 'Marsaawwan shaakala haasawaa fi jecha dubbisuuf safartuuwwan qabxii kennuu qindeessi. Dhuma marsaa shaakalaatti barattoonni qabxii fi yaada deebii AI\'n uumame argatan. <a href="{$a}" class="btn btn-sm btn-outline-primary ml-2">Safartuuwwan gulaali &rarr;</a>';
$string['settings:practice_scoring_enabled'] = 'Qabxii kennuu shaakalaa bani';
$string['settings:practice_scoring_enabled_desc'] = 'Yeroo banaa ta\'u, erga marsaawwan shaakala haasawaa fi jecha dubbisuu booda barattoonni kaardii qabxii madaallii safartuu tokkoon tokkoon fi yaada deebii qabu argatan.';
$string['settings:usertesting_heading'] = 'Qorannoo salphina fayyadamaa';
$string['settings:usertesting_heading_desc'] = 'Qorannoo salphina fayyadamaa widjeetii keessaa madaallii hojii irratti hundaa\'e waliin. Barattoonni gargaaraa keessatti hojiiwwan xumuran, muuxannoo isaaniis madaalan. Bu\'aawwan daashboordii xiinxalaa irratti mul\'atan.';
$string['settings:usertesting_enabled'] = 'Qorannoo salphina fayyadamaa bani';
$string['settings:usertesting_enabled_desc'] = 'Hidhaa "Qorannoo salphina fayyadamaa" jala widjeetii irratti agarsiisa. Yeroo banaa ta\'u, barattoonni hojiiwwan qorannoo argachuu danda\'an.';
$string['settings:usertesting_external_url'] = 'Teessoo unka alaa (gosa C)';
$string['settings:usertesting_external_url_desc'] = 'Filannoo: teessoo unka alaa (fakkeenyaaf Google Forms yookaan Typeform). Bakka qabattoota kanneen fayyadami: {{userid}}, {{courseid}}, {{messages}}, {{session_minutes}}. Yoo kaa\'ame, "Qorannoo salphina fayyadamaa" cuqaasuun teessoo kana haala qabiyyeen guutamee bana. Paanaalii qorannoo widjeetii keessaa qofa fayyadamuuf duwwaa dhiisi.';
$string['settings:footer_links_heading'] = 'Hidhaawwan jalaa';
$string['settings:footer_links_heading_desc'] = 'Hidhaawwan jala gargaaraa mul\'atan qindeessi: hidhaa filannoo tarreeffama koorsii hidhaa yaada deebii jala, akkasumas jechoota hidhaa yaada deebii fi paanaalii isaa.';
$string['settings:footer_courses_text'] = 'Barreeffama hidhaa koorsii';
$string['settings:footer_courses_text_desc'] = 'Barreeffama hidhaa hidhaa yaada deebii jala mul\'atu. Hidhaa guutummaatti dhoksuuf duwwaa dhiisi.';
$string['settings:footer_courses_url'] = 'Teessoo hidhaa koorsii';
$string['settings:footer_courses_url_desc'] = 'Iddoo hidhaan koorsii itti geessu (caancala haaraa keessatti bana). Dirree kun duwwaa yoo ta\'e hidhaan dhokata.';
$string['settings:feedback_link_label'] = 'Asxaa hidhaa yaada deebii';
$string['settings:feedback_link_label_desc'] = 'Barreeffama hidhaa yaada deebii jalaa bakka bu\'a, fakkeenyaaf "Yaada waa\'ee [[tutorshort]] garee IT\'tti ergi". Asxaa durtii hiikame "Yaada deebii" fayyadamuuf duwwaa dhiisi.';
$string['settings:feedback_panel_intro'] = 'Seensa paanaalii yaada deebii';
$string['settings:feedback_panel_intro_desc'] = 'Sarara seensaa gubbaa paanaalii yaada deebii irratti mul\'atu. Yaadni eessa akka deemu ibsa. Sarari seensaa akka hin jiraatuuf duwwaa dhiisi.';
$string['settings:quiz_provider'] = 'Dhiyeessaa gargaaraa qormaataa';
$string['settings:quiz_provider_desc'] = 'Eenyummeessaa dhiyeessaa (fakkeenyaaf <code>claude</code> yookaan <code>openai</code>) qormaata uumuuf. Sarara tokko Dhiyeessitoota walbira qabiinsaa keessa jiru waliin walsimuu qaba. Dhiyeessaa haasawaa fayyadamuuf duwwaa dhiisi.';
$string['settings:quiz_model'] = 'Moodela gargaaraa qormaataa';
$string['settings:quiz_model_desc'] = 'Maqaa moodelaa qormaata uumuuf, fakkeenyaaf <code>claude-haiku-4-5</code>. Bakka bu\'insi akka hojjetuuf dirreen kunis dhiyeessaanis lamaan guutamuu qabu.';
$string['settings:branding_heading'] = 'Eenyummaa maqaa oomishaa';
$string['settings:branding_heading_desc'] = 'Maqaa fi bifa gargaaraa qindeessi.';
$string['settings:institution_short_name'] = 'Maqaa gabaabaa dhaabbataa';
$string['settings:institution_short_name_desc'] = 'Maqaa gabaabaa dhaabbataa qaamota fuula fayyadamaa bakka dhiphoo qabaniif (fakkeenyaaf "State U").';
$string['settings:display_name'] = 'Maqaa mul\'atu gargaaraa';
$string['settings:display_name_desc'] = 'Maqaa guutuu gargaaraa AI, akka nagaa gaafannaa fi iskiriinii simannaa irratti mul\'atu (fakkeenyaaf "Gargaaraa Barnoota Toora Interneetii").';
$string['settings:short_name'] = 'Maqaa gabaabaa gargaaraa';
$string['settings:short_name_desc'] = 'Maqaa gabaabaa sarara mataduree fi qaamota fuula fayyadamaa bakka dhiphoo qabanitti fayyadamu (fakkeenyaaf "Gargaaraa").';
$string['settings:welcome_message'] = 'Ergaa iskiriinii simannaa';
$string['settings:welcome_message_desc'] = 'Ergaa daawwannaa jalqabaatti iskiriinii simannaa irratti mul\'atu. Maqaa barataaf <code>{{firstname}}</code> fi maqaa koorsiif <code>{{coursename}}</code> fayyadami. Barreeffama durtiif duwwaa dhiisi.';
$string['settings:chat_greeting'] = 'Nagaa gaafannaa haasawaa';
$string['settings:chat_greeting_desc'] = 'Ergaa nagaa gaafannaa foddaan haasawaa yeroo banamu mul\'atu. Maqaa barataaf <code>{{firstname}}</code> fi maqaa koorsiif <code>{{coursename}}</code> fayyadami. Barreeffama durtiif duwwaa dhiisi.';
$string['settings:customavatars'] = 'Fakkiiwwan dhuunfaa';
$string['settings:customavatars_desc'] = 'Tarreeffama fakkii gubbaa irratti dabaluuf suuraawwan PNG yookaan SVG roga afurii asitti olkaa\'i. Faayilii olkaa\'ame tokkoon tokkoon isaa durtii filatamu ta\'a (durduubee "Custom:" waliin). Tarreeffama gadi bu\'u irraa baasuuf faayilii tarreeffama kana irraa haqi. Yaada: PNG 256×256 iskiriinii Retina irratti ifatti mul\'ata.';
$string['settings:anomaly_digest_heading'] = 'Learning Radar — cuunfaa haala idilee hin taane';
$string['settings:anomaly_digest_heading_desc'] = 'Qorannoo guyyuu yeroowwan sochoo\'an sadarkaa gadhee, baasii tokens, fi mallattoo amanamummaa walbira qabu. Yeroo agarsiisaan daangaa qindaa\'e darbu, cuunfaan gara karaawwan qindaa\'anitti ergama. Gabaasa gaaffii tokkoon tokkoon isaatti yeroon qindaa\'aniif, paanaalii Sagantaa fuula xiinxalaa [[tutorshort]] irra jiru fayyadami.';
$string['settings:anomaly_digest_enabled'] = 'Cuunfaa haala idilee hin taane bani';
$string['settings:anomaly_digest_enabled_desc'] = 'Hojii guyyuu cuunfaa haala idilee hin taane hojjeta. Durtiidhaan calluu — agarsiisaan daangaa yeroo darbu qofa hojjeta.';
$string['settings:anomaly_digest_threshold_pct'] = 'Daangaa akeekkachiisaa (%)';
$string['settings:anomaly_digest_threshold_pct_desc'] = 'Jijjiirama dhibbeentaa yeroo dhiyoo fi yeroo duraanii gidduu jiru akeekkachiisa kaasu. Durtii: 50.';
$string['settings:anomaly_digest_recipient_email'] = 'Teessoo imeelii fudhataa';
$string['settings:anomaly_digest_recipient_email_desc'] = 'Teessoo imeelii cuunfaa haala idilee hin taane fudhatu. Teessoo bulchaa marsariitii fayyadamuuf duwwaa dhiisi.';
$string['settings:anomaly_digest_slack_webhook'] = 'Teessoo webhook galaa Slack';
$string['settings:anomaly_digest_slack_webhook_desc'] = 'Teessoo webhook galaa Slack filannoo. Cuunfaan akka ergaa bloki Slack maxxanfama.';
$string['settings:anomaly_digest_teams_webhook'] = 'Teessoo webhook galaa Microsoft Teams';
$string['settings:anomaly_digest_teams_webhook_desc'] = 'Teessoo webhook galaa Teams filannoo. Cuunfaan akka kaardii walqunnamsiisaa Office 365 maxxanfama.';

$string['settings:embed_query_model'] = 'Moodela gaaffii galchuu (olaanaa)';
$string['settings:embed_query_model_desc'] = 'Isa barbaaddu ta\'uu yoo mirkaneessite malee duwwaa dhiisi. Akkuma barameetti gaaffiiwwanii fi qabiyyeen koorsii moodela tokkoon galchamu, kunis filannoo yeroo hunda nagaa ta\'e qofa: vektaroonni moodeloota adda addaa irraa dhufan wal madaalamuu hin danda\'an, isaan makuun dogoggora agarsiisuu mannaa bu\'aa amanamaa fakkaatu garuu hiika hin qabne kenna. Kana kaa\'i yoo moodelonni lamaan iddoo galchuu tokko qooddatan qofa — amma maatii Voyage 4 (voyage-4-large, voyage-4, voyage-4-lite, voyage-4-nano), kanneen wal jijjiiruu danda\'an jedhamanii galmeeffaman. Faayidaan isaa katalogii koorsii keessan guutuu irra deebi\'anii galchuu malee booda moodela gaaffii jijjiiruu dandeessu. Yoo moodelonni wal madaalamuu hin danda\'an ta\'anii argaman, argachuun akeekkachiisa galmeessa, kutaa dogoggoraa deebisuu mannaa koorsii sanaaf homaa hin deebisu.';
$string['settings:embed_dtype'] = 'Sirrummaa vektara kuufame';
$string['settings:embed_dtype_desc'] = 'Vektarri kuufame tokkoon tokkoon isaa bakka hangam qabata. Sirrummaan gadi aanaan bakka diskii baay\'ee qusata, garuu sirrummaa argachuu xiqqoo hir\'isa. <strong>Kana jijjiiruun irra deebi\'anii guutummaatti indeeksii gochuu barbaachisa</strong> — caasaaleen walii galaan dubbifamuu hin danda\'an, koorsiin kamiyyuu ammas caasaa duraanii keessa kuufame irra deebi\'ee indeeksii hanga ta\'utti darbaa (akeekkachiisa galmee keessatti). Warri hir\'isuu deeggaran qofti kana kabaju; kaan yeroo hunda sirrummaa guutuun kuusu.';
$string['settings:embed_dtype_float'] = 'Sirrummaa guutuu (guddaa, sirrii ta\'e)';
$string['settings:embed_dtype_int8'] = 'Sirrummaa hir\'ate — gara harka afur keessaa tokko bakka';
$string['settings:embed_dtype_binary'] = 'Xiqqaa — gara harka soddoma keessaa tokko bakka, sirrummaa gadi aanaa';

$string['ragadmin:stat_vector_storage'] = 'Kuusaa vektaraa';
$string['ragadmin:storage_projection'] = 'Sirrummaa adda ta\'een irra deebi\'anii indeeksii gochuun kana gara kanaa jijjiira: {$a}. Sirrummaa jijjiiruun irra deebi\'anii guutummaatti indeeksii gochuu barbaachisa.';
$string['ragadmin:storage_alt_item'] = '{$a->dtype} — gara {$a->size}';

$string['settings:embed_dtype_shortfloat'] = 'Sirrummaa guutuu';
$string['settings:embed_dtype_shortint8'] = 'Sirrummaa hir\'ate';
$string['settings:embed_dtype_shortbinary'] = 'Xiqqaa';

$string['quizlock:blocked'] = 'Gargaaraan [[tutorshort]] yeroo qormaanni deemsa irra jiru hin argamu. Yaalii kee galchi ykn cufi, ergasii ammas ni argama.';
$string['quizlock:heading'] = 'Haala qormaataa';
$string['quizlock:enabled'] = 'Yeroo qormaata Moodle gargaaraa cufi';
$string['quizlock:enabled_desc'] = 'Bakka hundatti gargaaraa dhorka — haasawa, sagalee, kaardii yaadannoo, qormaata shaakalaa — yeroo barataan yaalii qormaataa deemsa irra jiru qabu. Sarvarii irratti ni mirkanaa\'a, kanaaf caancala lammaffaa banuun hin oolchu. Barsiisaan sadarkaa gargaarsa qormaata tokkoo Gargaarsa guutuu gochuun addaan baasuu danda\'a.';
$string['quizlock:window'] = 'Yeroo yaaliin itti fudhatama qabu (daqiiqaa)';
$string['quizlock:window_desc'] = 'Yaaliin qormaata daangaa yeroo hin qabne irratti hangam yeroo akka deemaa jirutti lakkaa\'ama. Qormaanni daangaa mataa isaa qabu isa fayyadama. Yaaliiwwan gataman daangaa malee deemaa turu, kanaaf daangaa kana malee tokko barataa bara baraan cufa ture. Durtii: 180.';

$string['emergency:chat_stopped'] = '[[tutorshort]] yeroo ammaa dhaabbateera. Meeshaaleen barnoota keessanii hin miidhamne, kunis dogoggora keessan miti — maaloo booda irra deebi\'aa yaalaa.';
$string['settings:money_nonnegative_invalid'] = 'Baay\'ina 0 ykn isaa ol galchaa, iddoo kurnyee lama caalaa hin taane (fakkeenyaaf 25 ykn 25.50).';

$string['chat:turn_failed'] = 'Deebiin kun xumuramuu hin dandeenye. Wanti ati goote tokkollee kanaaf sababa hin taane — mee irra deebi\'ii yaali.';
$string['settings:prompt_budget_mode'] = 'Haala baajata gaaffii sirnaa';
$string['settings:prompt_budget_mode_desc'] = 'Baajanni qubee gaaffii sirnaa akkamitti akka murtaa\'u. <strong>Moodeela irraa argachuu</strong> iddoo moodeelli qindaa\'e dhugumaan kennu ni shallaga — foddaa hiikaa isaa irraa deebii qabame fi seenaa haasawaa hir\'isee — sanas ni fayyadama, daangaa ol\'aanaa waliin, akka foddaan baay\'ee guddaan gaaffii baay\'ee guddaa hin heyyamneef. Kunis kan hojjetu yeroo baajanni qubee gadii jiru gatii durtii 36,000 irratti hafutti qofa: lakkoofsa sana yoo jijjiirte, isatu injifata, karaa lamaanuu, sababiin isaas lakkoofsi bulchaan barreesse tilmaama utuu hin taane murtoo waan ta\'eef. <strong>Kan hin jijjiiramne</strong> yeroo hunda lakkoofsa gadii fayyadama. Duubbeen ofiin kuufamu foddaa hiikaa duubbee qindeessuu qaba; sunis waan asii jiru hunda irra dursa qaba.';
$string['settings:prompt_budget_mode_auto'] = 'Moodeela irraa argachuu (kan gorfamu)';
$string['settings:prompt_budget_mode_fixed'] = 'Baajata qubee hin jijjiiramne';

$string['quizlock:scope'] = 'Cufaan hangam akka ga\'u';
$string['quizlock:scope_course'] = 'Koorsii kana qofa (kan gorfamu)';
$string['quizlock:scope_site'] = 'Koorsiiwwan hunda';
$string['quizlock:scope_desc'] = 'Yaaliin adeemsa irra jiru [[tutorshort]] koorsii qormaanni sun keessa jiru qofa keessatti dhorku, moo bakka hundatti. <strong>Koorsii kana qofa</strong> durtii yoo ta\'u, kan barbaadamu yeroo hunda gandaa. Marsariitii guutuu hanga v7.2.4 amala ture, rakkoo beekamuu qabus qaba ture: yaaliin gatame bara baraan «adeemsa irra» ta\'ee hafa, kanaafuu qormaanni tokko seenaa barataa keessatti irraanfatame koorsii inni fudhatu hunda keessatti gargaaraa sana ni dhaamsa ture, ibsi tokkoyyuu iskiriinii irratti utuu hin mul\'atiin. Marsariitii guutuun barataa hanna gochuuf murteeffate irratti waan xiqqoo qofa buusa, inni biraawuzarii lammaffaa qaba, meeshaan barnootaa fi barbaachi gargaaraa sanaas dursanii koorsiitti daangeffamaniiru.';

$string['settings:prompt_budget_tuner_conflict'] = 'Hojiin sirreeffama ofumaa baajata gaaffii kan hafe banaa dha, haalli baajataa garuu moodeela irraa akka argamu qindaa\'eera. Lamaan kun walitti bu\'u: hojiin sun baajata qubee barreessa, gatiin durtii hin taane kamiyyuu filannoo beekamaadhaan godhame jedhamee dubbifama, kunis baajata argame ni dhaamsa. Hojiin sun haala kana keessatti amma ofumaa dhaabata, kanaaf wanti irratti barreeffamu hin jiru — haa ta\'u malee shakkii balleessuuf dhaamsi.';

$string['settings:prompt_budget_no_window'] = 'Haalli baajata armaan olii moodeelicha irraa akka argamu qindaa\'eera, garuu wanti irraa argamu hin jiru: moodeelli haasawaa hin qindoofne, foddaan haala duubbee illee hin qindoofne, kanaaf argannoon sun gara baajata qubee dhaabbataa armaan gadiitti deebi\'a. Moodeela haasawaa qindeessi, yookaan foddaa haala duubbee harkaan qindeessi, ergasii qorannoo ofii duubbee irra deebi\'ii yaali, akkasumas qorannoon foddaa haalaa akka dabre mirkaneessi. Hanga sanaatti, haalli waan barbaade haa jedhu malee, baajanni lakkoofsa armaan gadii ti.';

