$string['settings:bench_default_samples'] = 'Promtiiwwan hojii tokkoon';
$string['settings:bench_default_samples_desc'] = 'Benchmark weeb irraa tarree keessa kaa\'ame promtii meeqa erga. Promtiin tokkoon tokkoon waamicha moodeelii live lama baasii qaba — deebii fi judge — kanaafuu kun buuftuu baasii ti. Koodii keessatti 50 irratti daangeffame, kunis guddina tuuta golden akkasumas waan hojii tokko daangaa rate dhiyeessaa keessatti eegu.';
$string['settings:bench_heading'] = 'Benchmark moodeelaa';
$string['settings:bench_heading_desc'] = 'Hojiin benchmark tokko promtii 50 deebisa, moodeelii judge tokko deebii hunda ruubrikii irratti qabxii kennisiisa, sana booda sarara tokko kuusa: giddu-gala ruubrikii, baasii waamicha tokkoo, fi yeroo baayitii jalqabaatti. Hojiiwwan fuula galmee moodeelaa irraa tarree keessa kaa\'amu, croniin hojjetamu.';
$string['settings:bench_judge_model'] = 'Moodeelii judge';
$string['settings:bench_judge_model_desc'] = 'Moodeelii deebiiwwan qabxii kennu. Isa jijjiiruun hiika qabxii sana booda fudhatamu hunda jijjiira, kanaafuu hojiin hundi judge itti fayyadame fi release piluginii irratti hojjete galmeessa.';
$string['settings:bench_judge_provider'] = 'Dhiyeessaa judge';
$string['settings:bench_judge_provider_desc'] = 'Dhiyeessaa moodeelii deebiiwwan qabxii kennuuf. Kuusaa dorgomtootaa keessaa isa baasi: moodeelii tokko of madaaluu hin qabu.';
$string['settings:bench_min_quality_n'] = 'Daangaa wal-madaalummaa (wantoota qabxii kennaman)';
$string['settings:bench_min_quality_n_desc'] = 'Hojiin kuufame wantoota qabxii kennaman xiqqaa hamma kam qabaatee hojii biraa waliin wal bira qabamuu danda\'a. Hojiiwwan daangaa gadi jiran ni kuufamu, ni mul\'ifamu, akka wabiif qofaatti mallatteeffamu, kanaafuu hojiin smoke promtii sadii qabu gonkumaa bu\'aa promtii shantamaa caaluu hin danda\'u. Durtii ijaarame fayyadamuuf 0 irratti dhiisi; daangaan 0 eegumsa kana ni diiga.';
$string['settings:embed_input_type_asymmetric'] = 'Wal-hin madaalle gaaffii/galmee (kan gorfamu)';
$string['settings:embed_input_type_mode'] = 'Gosa galchaa embedding';
$string['settings:embed_input_type_mode_desc'] = 'Embeddings Voyage qofaaf. Voyage barreeffama gaaffii ykn galmee ta\'uu isaa irratti hundaa\'uun karaa adda addaatiin agarsiisa. "Wal-hin madaalle" yeroo deebisanitti input_type=query, yeroo tarreeffamutti immoo input_type=document erga. Kun waan dhiyeessaan yaade yoo ta\'u, walitti qabaa kana irrattis kan hunda caalaa gaarii ta\'ee safarame kanuma: gama gaaffii irratti agarsiisa galmee fayyadamuun recall irraa qabxii dhibbentaa 30.8 kaffalchiise; sadarkaa dheerina gaaffii hunda keessattis kufe (2026-08-21, voyage-3.5, tuuta bocaa oomishaa). "Iddoo waliinii" gama lamaan irrattuu input_type=document erga; safaramuu danda\'uun caalaatti hir\'ataa deebisa, kanaafis akka wabii ce\'umsaatti qofa jira, sababiin isaas agarsiisni tokko qofti jiraachuun walitti qabaa sana irra deebi\'anii embed gochuu malee moodela gaaffii jijjiiruu waan dandeessisuuf. Ce\'umsa gidduu yoo hin jiraanne, wal-hin madaalle filadhu. Kana jijjiiruun irra deebi\'anii tarreessuu hin barbaachisu: kan jijjiiramu agarsiisa gama gaaffii qofa. Kun walitti qabsiisuu moodelaa wal-hin madaalle MITI (moodela Voyage isa ittiin gaafattu caalaa guddaa ta\'een tarreessuu) — sun mala biraa yoo ta\'u, walitti qabaa kana irratti si\'a lama irra deebi\'amuu hin dandeenye; innis qindaa\'ina moodela gaaffiitiin toʼatama malee qindaa\'ina kanaan miti.';
$string['settings:embed_input_type_shared'] = 'Iddoo waliinii (wabii ce\'umsaa; deebisuun hir\'ataadha)';
$string['settings:embed_migration_heading'] = 'Ceehumsa moodeelii embedding';
$string['settings:embed_migration_heading_desc'] = 'Moodeelii embedding yookiin bal\'ina isaa jijjiiruun vektara kuufame hunda ni diiga: retriever gaaffii chunks iddoo embedding biraa irraa dhufan waliin qabxii kennuu dida, kanaafuu koorsiin hamaa argachuu mannaa homaa hin argatu. Qindaa\'inoonni kunneen moodeelii ITTI deemtu ibsu. Sana booda koorsiiwwan fuula indeeksii RAG irraa tokko tokkoon irra deebi\'anii embed godhamu, vektaroonni haaraan kanneen durii cinaatti barreeffamu, akkasumas qindaa\'inoonni armaan olii hanga ati ofii kee jijjiirtutti argannoo tajaajilaa turu.';
$string['settings:embed_migration_provider_inherit'] = 'Dhiyeessaa armaan olitti qindaa\'e fayyadami';
$string['settings:embed_migration_target_apikey'] = 'Furtuu API dhiyeessaa galmaa';
$string['settings:embed_migration_target_apikey_desc'] = 'Yeroo dhiyeessaan galmaa isa armaan olitti qindaa\'e irraa adda ta\'u qofa barbaachisa. Duwwaan furtuu embedding jiru fayyadami jechuu dha.';
$string['settings:embed_migration_target_dimensions'] = 'Bal\'ina embedding galmaa';
$string['settings:embed_migration_target_dimensions_desc'] = 'Bal\'ina vektaraa yeroo ceehumsaa gaafatamu. 0 jechuun bal\'ina uumamaa moodeelichaa jechuu dha. Voyage 256, 512, 1024 fi 2048 fudhata; bal\'inni moodeelichi hin dhiyeessine ergamuu mannaa gaaffii keessaa hafa, kunis callisaan bal\'ina uumamaa isa ati gaafatte mannaa siif kenna.';
$string['settings:embed_migration_target_model'] = 'Moodeelii embedding galmaa';
$string['settings:embed_migration_target_model_desc'] = 'Maqaa moodeelii yeroo ceehumsaa ittiin embed godhamu, fakkeenyaaf <code>voyage-4-large</code>. Duwwaan ceehumsi hin qindeeffamne jechuu dha, fuulli indeeksii RAG tokko illee hin dhiyeessu.';
$string['settings:embed_migration_target_provider'] = 'Dhiyeessaa embedding galmaa';
$string['settings:embed_migration_target_provider_desc'] = 'Dhiyeessaa duraanuu armaan olitti qindaa\'e keessatti ceehumsiisuuf duwwaa dhiisi.';
$string['settings:rerank_min_query_chars'] = 'Rerank: dheerina gaaffii xiqqaa';
$string['settings:rerank_min_query_chars_desc'] = 'Gaaffiiwwan qubee hamma kanaa yookiin gadi ta\'aniif re-ranker dabarsi. Gaaffiiwwan gabaabaan bifa jecha-furtuu qabu, akkasumas re-ranker jechoota lama yookiin sadii irratti wal-fakkaatinni cosine irra homaa hin dabalu. Tuuta fixture RAG irratti safarame: 50 irratti daangessuun recall 67.7% argate, yeroo hunda-banaa 67.2% argate, baasii harka sadaffaa gara ta\'een. Gaaffii hunda rerank gochuuf 0 irratti kaa\'i. Reranks dabarfaman akka "[Rerank skipped: short_query]" jedhamee galmee ergaa keessatti galmeeffamu, kanaafuu daangaan hojjechuu isaa mirkaneeffachuu dandeessa.';
$string['settings:spend_export_key'] = 'Furtuu baasa baasii';
$string['settings:spend_export_key_desc'] = 'Furtuu Bearer endpoint baasa baasii AI ji\'aa <code>/local/ai_course_assistant/spend_export.php</code> irra jiruuf, kan daashboordiin baasii ji\'atti al tokko fudhatu. Endpoint cufuuf duwwaa dhiisi — sana booda gaaffii hundaaf 404 deebisa. Furtuun QOFA header <code>Authorization: Bearer</code> keessatti fudhatama, gonkumaa URL keessatti miti. Gatii dheeraa tasaa uumi; namni isa qabu baasii AI marsariitii guutuu dubbisuu danda\'a. Baasi milkaa\'e hundi galmee odiitii piluginii keessatti galmeeffama.';
