$string['settings:anomaly_digest_floor_usd'] = 'Cuunfaa jeequmsaa: baasii xiqqaa akeekkachiisni irratti ergamu (USD)';
$string['settings:anomaly_digest_floor_usd_desc'] = 'Yoo sa\'aatiin 24 darban kana gadi baasan, utaalchi dhibbeentaa hangam guddaa ta\'ellee akeekkachiisa baasii tokeenii ugguri. Dhibbeentaan bu\'uura xiqqaa irratti hundaa\'e sagalee duwwaa dha: $1 irraa gara $2 dachaa ta\'uun daangaa kamiyyuu ni darba, garuu homaa hin agarsiisu. Kana gara lakkoofsa guyyaa dhugumaan si dammaqsuu barbaaddutti qindeessi. 0 daangaa gadii ni dhaamsa, akeekkachiisis dhibbeentaa qofa irratti hundaa\'ee ergama. Yoo baasiin yeroo sana keessaa kamiyyuu moodeelii kaardii gatii keessatti hin galmoofne irraa dhufe, gatiin isaa herregamuu waan hin dandeenyeef akeekkachiisni haala kamiin iyyuu ni ergama -- moodeeliin hin beekamne walmakaa keessa jiraachuun mataan isaa arguuf gatii qaba.';
$string['settings:prompt_truncated_warning'] = '[[tutorshort]] daangaa qubee guuttachuuf qabiyyee koorsii argame gaaffii sirnaa keessaa muruuf dirqameera; kan dhiyeenyaa {$a} irratti. Moodeelichi meeshaa koorsii retriever filate caalaa xiqqaadhaan deebii kennaa jira. Daangaa qubee gaaffii sirnaa armaan gadii ol kaasi, yookiin hamma argamu hir\'isi.';
$string['settings:radar_batch_enabled'] = 'Gabaasota sagantaa\'an sadarkaa baachiitti ergi';
$string['settings:radar_batch_enabled_desc'] = 'Durtiidhaan cufaadha. Yeroo banamu, gabaasni sagantaa\'e tokkoon tokkoon isaa gatii baachiitiin ergama, yeroo dhiyeessaan xumuretti immoo ni dhiyaata; kunis sa\'aatii 24 keessatti yeroo kamiyyuu ta\'uu danda\'a; hanga sanatti sagantaan haala "ergame" jedhu agarsiisa. Sagantaaleen dhiyeessaan isaanii sadarkaa baachii hin qabne akkuma walsimaatti fufu, kanaafuu gabaasni tokkollee qindaa\'ina kanaan hin badu. Yeroo cufamu, sagantaan hundi yaalii itti aanu irratti gara karaa walsimaatti deebi\'a, baachiin karaa irra jiru kamiyyuu ammallee ni sassaabama, ni dhiyaatas.';
$string['settings:radar_batch_heading'] = 'Learning Radar: sadarkaa baachii offlaayinii';
$string['settings:radar_batch_heading_desc'] = 'Gabaasonni Learning Radar sagantaa\'an gara sadarkaa baachii offlaayinii dhiyeessaa AI ergamuu danda\'u; innis tokeenii galchaa fi bahaa lamaan irratti 50% qusata, kanaaf immoo deebiin hanga sa\'aatii 24 fudhachuu danda\'a. Gabaasonni SAGANTAA\'AN qofti ulaagaa guutu: Learning Radar yeroo barbaaddetti fuula kana irraa hojjettu deebii isaa gara biraawuzarii keetitti dhangalaasa, akkuma amaloota barataa mudatan hundaa yeroo hunda walsimaa ta\'ee hafa. Baasiin baachii maqaa moodeelii <code>batch/</code> jalqabu jalatti galmaa\'a, kanaafuu gabateen AI Spend gatii list osoo hin taane gatii hir\'ate agarsiisa.';
$string['settings:soapbox_deprecated_inuse'] = 'Soapbox ni dhiisame. PresenterAI, pilaagiinii sochii Moodle kan adda ta\'een bakka bu\'aa jira; innis waan Soapbox hojjetu hunda hojjeta, filannoo sochii keessatti ni mul\'ata, akkasumas kuusaa S3 fi kuusaa faayilii Moodle mataa isaa gidduutti, akkasumas AI Moodle core fi Claude, OpenAI yookiin Gemini kallattiin qindaa\'an gidduutti akka filattu si dandeessisa. Gadhiisa kana keessatti wanti jijjiiramu hin jiru: hojiiwwan kee, waraabbiin, transkiriiptiin, qabxiin fi yaadni akkuma jiranitti hafu, qindaa\'inni turtii akkuma duraanii hojjeta, hojiin qulqulleessuu guyyuus ammallee ni hojjeta. Koodichi v8.0.0 irratti haqamuuf sagantaa\'eera; hanga PresenterAI waraabbii fi qabxii duraan jiran galchuu danda\'utti gadhiisni tokkollee isa hin haqu. Gabateewwan daataabeezii adda addaan, yeroo booda immoo ni haqamu, sababiin isaas Soapbox galmee gradebook tokkollee waan hin barreessineef gabateewwan kun galmee dhiyeessa barataa isa qofaa waan ta\'aniifi. Maal gochuu qabda: amma Soapbox irratti koorsii haaraa ijaaruu dhaabi, PresenterAI yeroo gadhiifamu isa cinatti fe\'iitii hojii haaraaf isa fayyadami, koorsiiwwan Soapbox kee jiran immoo hanga galchuun argamutti hojjechaa hambisi. Barattoonni kee ammatti waa\'ee kanaa himamuu hin barbaachisan.';
$string['settings:soapbox_deprecated_off'] = 'Soapbox ni dhiisame, marsariitii kana irratti bakka kamiyyuu hin banamne. Akkuma cufametti dhiisi. PresenterAI, pilaagiinii sochii Moodle kan adda ta\'ee hojii walfakkaataa filannoo kuusaa fi dhiyeessaa AI waliin hojjetuun bakka bu\'aa jira. Koodichi v8.0.0 irratti haqamuuf sagantaa\'eera.';
