$string['analytics:total_tokens_hint'] = 'Kunis fudhannaa ni dabalata: waamicha embedding fi irra-deebi\'anii sadarkeessuu, kanneen saayitii RAG banaa qabu irratti lakkoofsa kana irra caalaan qabatan. Deebiiwwan marii asitti ni lakkaa\'amu garuu kutaa xiqqoo isaati. Lakkoofsi walga\'ii fi barataa fuula kana irratti bakka biraatti mul\'atu marii qofa safara; kanaafuu lamaan isaanii baay\'ee adda ta\'anii mul\'achuu danda\'u.';
$string['coursesettings:auto_open'] = 'Ofumaan banuu';
$string['coursesettings:auto_open_desc'] = 'Kuusaan [[tutorshort]] yeroo barataan tokko jalqabaaf koorsii kana qaqqabu ofumaan banamuu isaa to\'adhu. Haalli daawwannaa jalqabaa koorsii tokkoon tokkoon biraawzara barataa keessatti localStorage\'n hordofama. Durtiidhaan koorsiin kun qindaa\'ina idila-addunyaa (amma {$a}) dhaala.';
$string['coursesettings:auto_open_heading'] = 'Daawwannaa jalqabaa irratti ofumaan banuu';
$string['coursesettings:auto_open_help'] = 'Qindaa\'ina Ofumaan banuu idila-addunyaa koorsii kana qofaaf irra-deebi\'i.';
$string['coursesettings:back_to_course'] = 'Gara koorsiitti deebi\'i';
$string['coursesettings:course_analytics'] = 'Xiinxala koorsii';
$string['coursesettings:english_lock'] = 'Cufaa Ingiliffaa';
$string['coursesettings:english_lock_desc'] = 'Filannoo afaan barataa osoo hin ilaalin, koorsii kanaaf [[tutorshort]] yeroo hunda Ingiliffaan akka deebisu dirqisiisi. Koorsiiwwan barnoota afaan Ingiliffaa kanneen barattoonni Ingiliffaan dubbisuu fi barreessuu shaakaluu qabaniif baay\'ee mijataa dha.';
$string['coursesettings:english_lock_heading'] = 'Cufaa Ingiliffaa (Koorsiiwwan ELL)';
$string['coursesettings:english_lock_help'] = 'Yeroo dandeessifame, barataan afaan biraatiin yoo barreesse iyyuu [[tutorshort]] Ingiliffaan deebisa. Filannoon afaan barataa paanaalii qindaa\'ina isaa keessa jiru irra-deebi\'ama.';
$string['coursesettings:english_lock_toggle'] = 'Yeroo hunda Ingiliffaan deebisi';
