$string['coursesettings:force_on'] = 'Dirqiin bani';
$string['coursesettings:how_it_works'] = 'Qindaa\'inni koorsii akkamitti hojjeta:';
$string['coursesettings:how_it_works_desc'] = 'Qindaa\'inni as qindaa\'e koorsii kana qofaaf durtii idila-addunyaa irra-deebi\'a. Qindaa\'ina idila-addunyaa fayyadamuuf dirree duwwaa dhiisi. Jijjiiramni as taasifame koorsiiwwan biroo hin tuqu.';
