$string['coursesettings:voice_tab'] = 'Taabii Sagalee';
$string['coursesettings:voice_tab_desc'] = 'Taabii Sagalee (filannoo sagalee paanaalii qindaa\'inaa) koorsii kanaaf to\'adhu. Durtiidhaan qindaa\'ina idila-addunyaa (amma {$a}) dhaala.';
$string['coursesettings:voice_tab_help'] = 'Qindaa\'ina Taabii Sagalee idila-addunyaa koorsii kana qofaaf irra-deebi\'i.';
$string['pricedrift:eol_horizon'] = 'Daangaa akeekkachiisa dhuma-jireenyaa (guyyoota)';
$string['pricedrift:eol_horizon_desc'] = 'Sooramni moodeelii beeksifame hangam dursee gabaafamuu akka jalqabu. Sakatta\'iinsi drift gatii hordofa; kana malee wanti marsaa jireenyaa hordofu hin jiru, sooramni dhugaa immoo akka akeekkachiisaatti utuu hin taane akka addaan citiinsa oomishaatti dhufa — moodeelichi hamma dhaabatutti hojjechuu fi kaffalchiisuu itti fufa, ergasii waamichi hundi al tokkotti kufa. Durtiin guyyoota 60 ti, sababni isaas moodeelii oomishaa bakka buusuun qorannoo walbira qabiinsaa, jijjiirama qindaa\'inaatii fi diriirsa gaafata malee hojii waaree booda tokkoo miti. Sooramni guyyaan isaa darbe kamiyyuu, kun akkamitti illee yoo qindaa\'e, yeroo hunda ni gabaafama.';
$string['pricedrift:eol_surfaces'] = 'Fuulawwan API saayitiin kun waamu';
$string['pricedrift:eol_surfaces_desc'] = 'Kooman qoodame, fakkeenyaaf <code>gemini-developer-api,openai-api</code>. Sooramni beeksifame kan akeekkachiisu yoo fuulawwan kanneen keessaa tokkoof beeksifame qofa; kaan ammas ni mul\'atu, garuu kan kee akka hin taane mallatteeffamu. Dhuma jireenyaa galmaa\'e hundaaf akeekkachiisa argachuuf duwwaa dhiisi. Kun kan jiru sababa balaa dhugumatti nu darbeef: gemini-2.5-flash 2026-10-16 irratti akka sooramu gabaafamee ture, kunis marsaa jireenyaa Vertex AI irratti dhugaa ture malee Gemini Developer API pilaagiiniin kun waamu irratti miti. Waa\'ee waan hin taane tokkoof al tokko waamamuun namoonni akeekkachiisa itti aanu akka tuffatan barsiisa.';
$string['ragadmin:badge_off'] = 'Cufaa';
