$string['ragadmin:content_sources'] = 'Maddoota qabiyyee';
$string['ragadmin:content_sources_desc'] = 'Sararri tokkoon tokkoon gosa qabiyyee tarreessaan RAG barreeffama irraa baasuu danda\'u, akkasumas amma banaa fi hojjechuuf qophii ta\'uu isaa agarsiisa. Isaan keessaa kamiyyuu jijjiiruuf <a href="{$a}">Qindaa\'ina</a> bani.';
