$string['privacy:metadata:bench'] = 'Dalagaa safara dhiyeessaa: bu\'aa wal bira qabiinsa moodeelii kan bulchaan sayitii uume. Odeeffannoon dhuunfaa isa qofti eenyummeessituu bulchaa dalagaa sana jalqabee ti. Sararoonni kun odeeffannoo dhuunfaa barataa osoo hin taane qindaa\'ina sayitii waan ta\'aniif, baasuu daataa keessatti hin hammataman, akkasumas yeroo fayyadamaan haquu gaafatu hin haqaman.';
$string['privacy:metadata:bench:createdby'] = 'Bulchaa sayitii dalagaa safaraa kana jalqabe. Yeroo dalagaan sun sarara ajajaa irraa jalqabame duwwaa ta\'a.';
$string['privacy:metadata:models'] = 'Galmee moodeelii: gatii fi dandeettii moodeelii tokkoon tokkoon isaaf irra-deebi\'uu kan bulchaan sayitii kunuunsu. Odeeffannoon dhuunfaa isa qofti eenyummeessituu bulchaa galmicha dhumarratti olkaa\'e ti. Sararoonni kun odeeffannoo dhuunfaa barataa osoo hin taane qindaa\'ina sayitii waan ta\'aniif, baasuu daataa keessatti hin hammataman, akkasumas yeroo fayyadamaan haquu gaafatu hin haqaman.';
$string['privacy:metadata:models:addedby'] = 'Bulchaa sayitii galmee moodeelii kana dhumarratti olkaa\'e. Yeroo galmichi sooraa gatii ofumaan hojjetuun barreeffame duwwaa ta\'a.';
$string['privacy:metadata:pricesrc'] = 'Ibsa sooraa gatii: tarree gatii gurgurtootaa kan bulchaan sayitii akka pilagiiniin fudhatu qindeesse. Odeeffannoon dhuunfaa isa qofti eenyummeessituu bulchaa sooraa sana dabalee ti. Sararoonni kun odeeffannoo dhuunfaa barataa osoo hin taane qindaa\'ina sayitii waan ta\'aniif, baasuu daataa keessatti hin hammataman, akkasumas yeroo fayyadamaan haquu gaafatu hin haqaman.';
$string['privacy:metadata:pricesrc:addedby'] = 'Bulchaa sayitii sooraa gatii kana dabale. Yeroo sooraan sun pilagiinii waliin dhufu duwwaa ta\'a.';
$string['privacy:metadata:sbx_assign'] = 'Ramaddii dhiyeessa Soapbox: hojii barsiisaan koorsiif qopheesse. Odeeffannoon dhuunfaa isa qofti eenyummeessituu miseensa hojjettootaa ramaddicha dhumarratti gulaalee ti. Sararoonni kun odeeffannoo dhuunfaa barataa osoo hin taane qindaa\'ina koorsii waan ta\'aniif, baasuu daataa keessatti hin hammataman, akkasumas yeroo fayyadamaan haquu gaafatu hin haqaman; kun ta\'uu isaa ramaddii barattoonni biroo ammallee irratti hojjetaa jiran ni jijjiira ture.';
$string['privacy:metadata:sbx_assign:usermodified'] = 'Miseensa hojjettootaa ramaddii dhiyeessa kana dhumarratti gulaale.';
$string['redash:err_deanonymized_disabled'] = 'Baasuun maqaa qabu hin dandeessifamne. anonymize=0 hayyamuuf qindaa\'ina pilagiinii "Allow de-anonymized export" dandeessisi.';
