$string['starters:howto_builtin'] = '<strong>Jalqabsiiftuuwwan ijaaraman</strong> sirnaan bulfamu. Dandeessisuu yookiin dhaabuu, mallattoo isaanii jijjiiruu fi tartiiba isaanii jijjiiruu ni dandeessa, garuu haquu hin dandeessu.';
$string['starters:howto_conditional'] = '<strong>Mul\'achuu haala qabu:</strong> jalqabsiiftuu sagaleetiif "Yeroo TTS dandeessifame qofa", jalqabsiiftuu dubbifamaatiif immoo "Yeroo Realtime dandeessifame qofa" filadhu. Yoo amalli barbaadame cufaa ta\'e, jalqabsiiftuun sun barattoota irraa ni dhokata.';
$string['starters:howto_custom'] = '<strong>Jalqabsiiftuu mataa keetii</strong> kan ati uumtu dha. Tokko uumuuf armaan gadii "{$a}" cuqaasi. Waan hunda gulaaluu ni dandeessa: maqaa, gaaffii, mallattoo fi haala mul\'achuu.';
$string['starters:howto_heading'] = 'Fuula kana akkamitti fayyadamta';
$string['starters:howto_overrides'] = '<strong>Irra-deebi\'uu koorsii tokkoon tokkoon:</strong> erga as jalqabsiiftuuwwan qindeessitee booda, jalqabsiiftuu murtaa\'e koorsii sanaaf dandeessisuuf yookiin dhaabuuf gara fuula qindaa\'ina koorsii tokkoon tokkoon isaatti deemi.';
